/// Ek flash kartlar (2. paket) — sözel desteler: Türkçe, Edebiyat, Tarih,
/// Coğrafya, Felsefe grubu, Din Kültürü ve İngilizce. DersNet için özgün
/// olarak hazırlanmıştır.
library;

import '../../data/models/flash_kart.dart';

FlashKart _k(String id, String ders, String unite, String on, String arka, [String? ipucu]) =>
    FlashKart(id: id, ders: ders, unite: unite, on: on, arka: arka, ipucu: ipucu);

const _tr = 'turkce';
const _edb = 'edebiyat';
const _tar = 'tarih';
const _cog = 'cografya';
const _fel = 'felsefe';
const _din = 'din';
const _ing = 'ingilizce';

final List<FlashKart> ekSozelKartlar = [
  // ─── TÜRKÇE ────────────────────────────────────────────
  _k('ktr-031', _tr, 'Ses Bilgisi', "Büyük ve küçük ünlü uyumu", "Büyük ünlü uyumu: kalın ünlüden (a, ı, o, u) sonra kalın, ince ünlüden (e, i, ö, ü) sonra ince ünlü gelir.\nKüçük ünlü uyumu: düz ünlüden sonra düz; yuvarlak ünlüden sonra dar yuvarlak (u, ü) ya da düz geniş (a, e) gelir.\nUymayanlar: kardeş, elma, anne; -yor, -ken, -ki, -leyin, -mtırak ekleri.", "-yor uyuma girmez"),
  _k('ktr-032', _tr, 'Ses Bilgisi', "Ulama", "Ünsüzle biten sözcükten sonra ünlüyle başlayan sözcük gelirse, ünsüz sonraki sözcüğün ilk hecesine bağlanarak okunur.\nÖrnek: “Arkadaşım okula geldi.” (arkadaşı-mokula)\nAraya noktalama işareti girerse ulama yapılmaz.", "Ünsüz + ünlü"),
  _k('ktr-033', _tr, 'Yazım Kuralları', "Birleşik sözcüklerin yazımı", "Bitişik: ses düşmesi ya da türemesi olanlar (kaybolmak, affetmek); anlam kayması olanlar (hanımeli, aslanağzı); kalıplaşmış fiiller (gelebilmek, bakakalmak).\nAyrı: ses değişimi olmayan yardımcı fiilli birleşikler (terk etmek, fark etmek, yok olmak).", "Ses değişirse bitişik"),
  _k('ktr-034', _tr, 'Yazım Kuralları', "Sayıların yazımı", "Birden fazla sözcüklü sayılar ayrı yazılır: on beş, iki yüz elli.\nÜleştirme sayıları yazıyla yazılır: ikişer, dokuzar.\nSıra sayıları: 5. ya da 5'inci.\nSaat ve dakika arasına nokta konur: 14.30.\nPara ile ilgili işlemlerde bitişik yazılabilir.", "On beş ayrı yazılır"),
  _k('ktr-035', _tr, 'Yazım Kuralları', "Kısaltmalara gelen ekler", "Büyük harfli kısaltmalarda ek, son harfin okunuşuna göre gelir ve kesmeyle ayrılır: TDK'nin, THY'de, TBMM'ye.\nKüçük harfli kısaltmalarda ek, sözcüğün okunuşuna göre gelir: kg'dan, cm'yi.\nNoktalı kısaltmalarda kesme kullanılmaz: vb.leri.", "TDK'nin (ke harfine göre)"),
  _k('ktr-036', _tr, 'Yazım Kuralları', "Yazımı sık karıştırılan sözcükler", "Doğru yazımlar: herkes, yalnız, yanlış, şoför, tıraş, kirpik, orijinal, egzoz, sürpriz, eşofman, entelektüel, kılavuz, meyve, pantolon, sarımsak, şemsiye, tespit, unvan, zürafa.", "Yalnız ve yanlış: kökü düşün"),
  _k('ktr-037', _tr, 'Noktalama İşaretleri', "Virgülün kullanıldığı yerler", "Eş görevli sözcük ve söz gruplarını ayırır.\nSıralı cümleleri ayırır.\nUzun cümlelerde özneyi belirtir.\nAra sözleri ve hitapları ayırır.\nTırnak içine alınmayan aktarma cümlelerinden sonra konur.\nMetin içinde “ve, veya, ya da” bağlaçlarından önce ya da sonra konmaz.", "Bağlaçtan önce virgül olmaz"),
  _k('ktr-038', _tr, 'Noktalama İşaretleri', "Tırnak, kısa çizgi, uzun çizgi ve üç nokta", "Tırnak işareti: aktarılan sözler ve vurgulanan sözcükler; tırnak içindeki cümlenin noktalama işareti tırnak içinde kalır.\nKısa çizgi: ara sözler, satır sonu, ekler ve kökler (-lık), arasında anlamı (2020-2024).\nUzun çizgi: karşılıklı konuşmalar.\nÜç nokta: tamamlanmamış cümleler.", "Konuşma çizgisi uzun"),
  _k('ktr-039', _tr, 'Sözcük Türleri', "İsim (ad) çeşitleri", "Varlıklara verilişine göre: özel isim, cins isim.\nOluşuna göre: somut, soyut.\nSayısına göre: tekil, çoğul, topluluk (ordu, sürü, orman, sınıf).\nTopluluk ismi çoğul eki almadan birden çok varlığı karşılar.", "Topluluk: ordu, sürü"),
  _k('ktr-040', _tr, 'Sözcük Türleri', "İsmin hâl ekleri", "Yalın hâl: eksiz (ev)\nBelirtme: -ı, -i, -u, -ü (evi)\nYönelme: -a, -e (eve)\nBulunma: -da, -de (evde)\nAyrılma: -dan, -den (evden)\nBelirtme ekini alan sözcük belirtili nesne; -e, -de, -den alanlar çoğunlukla dolaylı tümleç olur.", "-i, -e, -de, -den"),
  _k('ktr-041', _tr, 'Sözcük Türleri', "Sıfat (ön ad) çeşitleri", "Niteleme sıfatı: “nasıl?” (kırmızı kalem).\nBelirtme sıfatları: işaret (bu ev), sayı (asıl: üç, sıra: üçüncü, üleştirme: üçer, kesir: yarım), belgisiz (bazı insanlar, birkaç kişi), soru (hangi kitap, kaç kişi).\nSıfat mutlaka bir ismin önünde bulunur.", "İsmin önünde olmalı"),
  _k('ktr-042', _tr, 'Sözcük Türleri', "Adlaşmış sıfat ve sıfat tamlaması", "Sıfat tamlaması: sıfat + isim (yaşlı adam). Tamlanan ek almaz.\nAdlaşmış sıfat: nitelediği isim düşer, sıfat onun yerine geçer ve isim çekim eklerini alır: “Yaşlılar otobüse bindi.”\nPekiştirme: bembeyaz; küçültme: -ce, -cik, -msi, -mtırak.", "İsim düşer, sıfat adlaşır"),
  _k('ktr-043', _tr, 'Fiiller', "Fiil kipleri", "Haber (bildirme) kipleri: görülen geçmiş (-di), duyulan geçmiş (-miş), şimdiki (-yor), gelecek (-ecek), geniş (-r).\nDilek kipleri: gereklilik (-meli), istek (-e), dilek-şart (-se), emir (eksiz).\nDilek kiplerinde zaman anlamı yoktur.", "5 haber, 4 dilek"),
  _k('ktr-044', _tr, 'Fiiller', "Ek fiil (ek eylem)", "İki görevi vardır:\n1) İsim soylu sözcükleri yüklem yapar: “Hava güzeldi / güzelmiş / güzelse / güzeldir.”\n2) Basit zamanlı fiilleri birleşik zamanlı yapar: geliyor-du (hikâye), geliyor-muş (rivayet), geliyor-sa (şart).", "idi, imiş, ise, -dir"),
  _k('ktr-045', _tr, 'Fiiller', "Yapısına göre fiiller", "Basit: yapım eki almamış (gel-, oku-).\nTüremiş: yapım eki almış (göz-le-, yaz-dır-).\nBirleşik: kurallı (yeterlik: gelebil-, tezlik: geliver-, sürerlik: bakakal-, yaklaşma: düşeyaz-); yardımcı fiille kurulan (fark et-); anlamca kaynaşmış (göze gir-).", "Yeterlik, tezlik, sürerlik, yaklaşma"),
  _k('ktr-046', _tr, 'Fiiller', "Nesne – yüklem ilişkisi", "Geçişli: nesne alabilir (“neyi, kimi?” sorusuna yanıt verir): oku-, sev-.\nGeçişsiz: nesne alamaz: uyu-, gül-.\nOldurgan: geçişsiz fiil ekle geçişli olur (uyu-t-, gül-dür-).\nEttirgen: geçişli fiilin geçişlilik derecesi artar (oku-t-, yaz-dır-).", "Neyi, kimi?"),
  _k('ktr-047', _tr, 'Cümle Bilgisi', "Ögeleri bulma sırası ve kurallar", "Önce yüklem, sonra özne, ardından nesne, dolaylı tümleç ve zarf tümleci bulunur.\nTamlamalar, deyimler, birleşik fiiller bölünmez.\nAra söz, açıkladığı ögeyle aynı görevdedir.\nEdat grupları (için, ile, gibi) genellikle zarf tümleci (edat tümleci) olur.", "Önce yüklem"),
  _k('ktr-048', _tr, 'Cümle Bilgisi', "Anlamına ve yüklemine göre cümleler", "Anlamına göre: olumlu, olumsuz, soru, ünlem; biçimce olumsuz anlamca olumlu cümleler (“Gelmedi değil.”).\nYüklemin türüne göre: fiil cümlesi, isim cümlesi.\nYüklemin yerine göre: kurallı, devrik, eksiltili.", "İki olumsuz = olumlu"),
  _k('ktr-049', _tr, 'Sözcükte Anlam', "Sözcükler arası anlam ilişkileri", "Eş anlamlı: aynı anlam (siyah – kara).\nYakın anlamlı: benzer anlam (bezmek – usanmak).\nZıt anlamlı: karşıt anlam (iyi – kötü); olumsuzu zıddı değildir (gelmek – gelmemek).\nEş sesli (sesteş): yazılışı aynı, anlamı farklı (yüz, çay, kır).", "Olumsuz ≠ zıt anlam"),
  _k('ktr-050', _tr, 'Sözcükte Anlam', "Ad aktarması, dolaylama, güzel adlandırma", "Ad aktarması (mecazımürsel): benzetme amacı olmadan bir sözün başka söz yerine kullanılması (“Sobayı yaktım.”).\nDolaylama: tek sözcükle anlatılacak kavramın birden çok sözcükle anlatılması (file bekçisi, derya kuzusu).\nGüzel adlandırma: kaba sözün yerine uygun söz (hayatını kaybetmek).", "Dolaylama: birden çok sözcük"),
  _k('ktr-051', _tr, 'Sözcükte Anlam', "Somutlaştırma ve duyu aktarımı", "Somutlaştırma: soyut bir kavramın somut bir sözcükle anlatılması (“Umutları kırıldı.”).\nSoyutlaştırma: somut sözcüğün soyut anlam kazanması.\nDuyu aktarımı: bir duyuya ait sözcüğün başka bir duyu için kullanılması (tatlı ses, keskin koku, sıcak bakış).", "Tatlı ses: tat → işitme"),
  _k('ktr-052', _tr, 'Cümlede Anlam', "Cümlede anlam özellikleri", "Tanım: “Bu nedir?” sorusuna yanıt verir.\nKarşılaştırma: daha, en, kadar, göre.\nVarsayım: “diyelim ki, tut ki, farz edelim”.\nOlasılık: belki, galiba, -ebilir.\nÖn yargı (peşin hüküm): gerçekleşmeden varılan yargı.\nÖneri, eleştiri, öz eleştiri, tahmin, yakınma, sitem.", "Varsayım: tut ki"),
  _k('ktr-053', _tr, 'Paragraf', "Konu, ana düşünce, yardımcı düşünce, başlık", "Konu: parçada ne anlatıldığı.\nAna düşünce: yazarın asıl vermek istediği ileti; genellikle bir yargı cümlesidir.\nYardımcı düşünceler: ana düşünceyi destekleyen ayrıntılar.\nBaşlık: konuyu en kısa biçimde yansıtan söz.", "Konu ne, ana düşünce niçin"),
  _k('ktr-054', _tr, 'Paragraf', "Paragrafın yapısı", "Giriş cümlesi: konuyu tanıtır; kendinden önceye gönderme yapmaz, bağlayıcı sözle (çünkü, ama, bu yüzden) başlamaz.\nGelişme: konu açıklanır, örneklenir.\nSonuç: düşünce bir yargıya bağlanır.\nAkışı bozan cümle: konunun farklı bir yönüne geçen cümledir.", "Giriş cümlesi bağımsızdır"),
  _k('ktr-055', _tr, 'Paragraf', "Paragraf sorularında çözüm stratejisi", "Önce soru kökünü oku; olumsuz köklerin (değinilmemiştir, çıkarılamaz) altını çiz.\nSeçenekleri parçadaki ifadelerle eşleştirerek ele.\nKendi yorumunu değil, parçada yazanı esas al.\nAna düşünce sorularında genellikle son cümlelere dikkat et.", "Önce soru kökü"),
  _k('ktr-056', _tr, 'Paragraf', "Anlatımın nitelikleri", "Açıklık: tek anlama gelme.\nDuruluk: gereksiz sözcük bulunmaması.\nYalınlık: süsten uzak, sade anlatım.\nAkıcılık: kolay okunma.\nÖzgünlük: başkasına benzememe.\nYoğunluk: az sözle çok şey anlatma.\nÖzlülük, doğallık, tutarlılık.", "Duruluk: gereksiz sözcük yok"),
  _k('ktr-057', _tr, 'Anlatım Bozuklukları', "Sık görülen anlatım bozukluğu türleri", "Anlamsal: gereksiz sözcük (geri iade), çelişen sözler (kesinlikle… olabilir), yanlış anlamda kullanım (ücret/fiyat), mantık hatası, deyim yanlışı, sıralama hatası.\nYapısal: özne-yüklem uyumsuzluğu, öge eksikliği, ek ya da tamlama yanlışı, çatı uyumsuzluğu.", "Önce öge eksikliğine bak"),

  // ─── EDEBİYAT ──────────────────────────────────────────
  _k('kedb-031', _edb, 'Şiir Bilgisi', "Kafiye (uyak) türleri", "Yarım kafiye: tek ses benzerliği.\nTam kafiye: iki ses benzerliği.\nZengin kafiye: üç ve daha fazla ses benzerliği.\nTunç kafiye: bir sözcüğün diğerinin içinde yer alması.\nCinaslı kafiye: yazılışı aynı, anlamı farklı sözcüklerle.", "1 ses yarım, 2 tam, 3+ zengin"),
  _k('kedb-032', _edb, 'Şiir Bilgisi', "Kafiye düzenleri", "Düz kafiye: aaaa, aaab, aabb\nÇapraz kafiye: abab\nSarmal (sarma) kafiye: abba\nMani tipi kafiye: aaxa\nKoşma tipi kafiye: abab / cccb / dddb", "Sarmal: abba"),
  _k('kedb-033', _edb, 'Şiir Bilgisi', "Konularına göre şiir türleri", "Lirik: duygu ve coşku.\nEpik: kahramanlık, savaş.\nDidaktik: öğretici.\nPastoral: doğa, kır ve çoban yaşamı.\nSatirik: eleştiri, yergi.\nDramatik: sahnelenmek için yazılan manzum tiyatro.", "Pastoral: doğa"),
  _k('kedb-034', _edb, 'Söz Sanatları', "Teşbih (benzetme) ve ögeleri", "Benzeyen: zayıf olan varlık.\nKendisine benzetilen: güçlü olan varlık.\nBenzetme yönü: ortak özellik.\nBenzetme edatı: gibi, kadar, sanki, misal.\nYalnızca benzeyen ve kendisine benzetilenle yapılan benzetme: teşbih-i beliğ (güzel benzetme).", "Dört öge"),
  _k('kedb-035', _edb, 'Söz Sanatları', "Mecazımürsel (ad aktarması)", "Benzetme amacı güdülmeden bir sözün başka bir söz yerine kullanılmasıdır.\nİlişkiler: parça-bütün (“Bu kapı hepimizi besler.”), iç-dış (“Sobayı yaktık.”), yer-insan (“Bütün sınıf güldü.”), yazar-eser (“Orhan Veli'yi okudum.”).", "Benzetme yok"),
  _k('kedb-036', _edb, 'Söz Sanatları', "Tevriye, cinas, tenasüp, leff ü neşr", "Tevriye: iki anlamlı sözcüğün uzak anlamının kastedilmesi.\nCinas: yazılışı aynı, anlamı farklı sözcüklerin bir arada kullanılması.\nTenasüp: anlamca ilgili sözcüklerin birlikte kullanılması.\nLeff ü neşr: ilk dizede söylenenlerle ilgili açıklamaların ikinci dizede sıralanması.", "Tevriye: uzak anlam"),
  _k('kedb-037', _edb, 'Söz Sanatları', "Mübalağa, tezat, telmih, intak, tariz", "Mübalağa: abartma.\nTezat: karşıt kavramları bir arada kullanma.\nTelmih: bilinen bir olay, kişi ya da esere gönderme.\nİntak: insan dışı varlıkları konuşturma.\nTariz: söylenenin tam tersini kastederek iğneleme.", "Tariz: iğneleme"),
  _k('kedb-038', _edb, 'İslamiyet Öncesi', "Türk destanları", "Saka: Alp Er Tunga, Şu.\nHun: Oğuz Kağan.\nGöktürk: Bozkurt, Ergenekon.\nUygur: Türeyiş, Göç.\nİslamiyet sonrası: Satuk Buğra Han, Manas (Kırgız), Cengiz Han, Battalgazi, Danişmendname, Köroğlu.", "Göktürk: Ergenekon, Bozkurt"),
  _k('kedb-039', _edb, 'Geçiş Dönemi', "Geçiş dönemi eserleri", "Kutadgu Bilig (Yusuf Has Hacip): ilk mesnevi ve siyasetname, aruzla.\nDivanü Lügati't-Türk (Kaşgarlı Mahmud): ilk sözlük.\nAtabetü'l-Hakayık (Edip Ahmet Yükneki): ahlak ve öğüt kitabı.\nDivan-ı Hikmet (Ahmet Yesevi): tasavvufi şiirler, hece ölçüsüyle.", "Dört temel eser"),
  _k('kedb-040', _edb, 'Halk Edebiyatı', "Halk edebiyatının bölümleri", "Anonim halk edebiyatı: söyleyeni belli değil (mani, türkü, ninni, masal, halk hikâyesi).\nÂşık tarzı halk edebiyatı: saz şairleri (koşma, semai, varsağı, destan).\nDinî-tasavvufi (tekke) halk edebiyatı: ilahi, nefes, deme, nutuk, şathiye, devriye.", "Anonim, âşık, tekke"),
  _k('kedb-041', _edb, 'Tekke Edebiyatı', "Tekke edebiyatı nazım türleri", "İlahi: Allah'ı övmek için, ezgiyle.\nNefes: Bektaşi şairlerinin tasavvufi şiiri.\nDeme: Alevi-Bektaşi şiiri.\nŞathiye: inançlardan alaycı bir dille söz eder gibi görünen şiir.\nNutuk: müritlere tarikat adabını öğretir.\nDevriye: yaratılış döngüsünü anlatır.", "Nefes: Bektaşi"),
  _k('kedb-042', _edb, 'Halk Edebiyatı', "Anonim halk edebiyatı ürünleri", "Mani: 7 heceli, 4 dizeli, aaxa.\nTürkü: ezgili; bent ve kavuştaktan oluşur.\nNinni, ağıt, tekerleme, bilmece.\nMensur ürünler: masal, efsane, halk hikâyesi (Kerem ile Aslı), fıkra, atasözü, Karagöz, orta oyunu, meddah.", "Türküde kavuştak tekrarlanır"),
  _k('kedb-043', _edb, 'Divan Edebiyatı', "Mesnevi", "Her beyti kendi içinde kafiyelidir (aa bb cc…).\nBeyit sayısı sınırsızdır; uzun olaylar anlatılır.\nBeş mesneviden oluşan esere “hamse” denir.\nÖnemli örnekler: Leyla ile Mecnun (Fuzûlî), Hüsn ü Aşk (Şeyh Galip), Harname (Şeyhî), Mantıku't-Tayr çevirisi (Gülşehrî).", "aa bb cc"),
  _k('kedb-044', _edb, 'Divan Edebiyatı', "Bentlerle kurulan nazım biçimleri", "Murabba: dörtlüklerle.\nŞarkı: Türklerin divan şiirine kattığı biçim; bestelenmek için yazılır (Nedîm).\nTerkib-i bent ve terci-i bent: bentlerin sonunda “vasıta beyti” bulunur; terci-i bentte bu beyit aynen yinelenir.\nMüstezat: uzun dizeye kısa dize eklenmesi.", "Şarkı ve tuyuğ Türk icadı"),
  _k('kedb-045', _edb, 'Divan Edebiyatı', "Divan edebiyatı nazım türleri", "Tevhid: Allah'ın birliği.\nMünacat: Allah'a yakarış.\nNaat: Hz. Muhammed'e övgü.\nMersiye: ölüm üzerine yas.\nMethiye: övgü.\nHicviye: yergi.\nFahriye: şairin kendini övmesi.\nSurname: düğün ve şenlikler.\nŞehrengiz: bir şehrin güzellikleri.", "Naat: peygambere övgü"),
  _k('kedb-046', _edb, 'Divan Edebiyatı', "Divan nesri ve türleri", "Sade nesir: halk için, yalın dille.\nOrta nesir: tarih, gezi kitapları.\nSüslü (sanatlı) nesir: sanat göstermek amaçlı; secili.\nTürler: tezkire (şair biyografileri), münşeat (mektup ve yazı örnekleri), seyahatname, sefaretname, siyasetname.", "Tezkire: şairler kitabı"),
  _k('kedb-047', _edb, 'Divan Edebiyatı', "Yüzyıllara göre divan şairleri", "13–14. yy: Hoca Dehhani, Ahmedî, Kadı Burhaneddin.\n15. yy: Şeyhî, Ahmet Paşa, Necati, Ali Şir Nevai.\n16. yy: Fuzûlî, Bâkî, Zatî, Bağdatlı Ruhî.\n17. yy: Nef'î (hiciv, kaside), Nâbî (hikemî), Nâilî.\n18. yy: Nedîm (mahallîleşme), Şeyh Galip.", "16: Fuzûlî ve Bâkî"),
  _k('kedb-048', _edb, 'Tanzimat', "Tanzimat I. dönem özellikleri", "“Sanat toplum içindir” anlayışı.\nVatan, millet, hürriyet, adalet kavramları.\nDilde sadeleşme istenmiş ama tam uygulanamamıştır.\nRomantizm etkisi.\nSanatçılar: Şinasi, Namık Kemal, Ziya Paşa, Ahmet Mithat, Şemsettin Sami, Ahmet Vefik Paşa.", "Toplum için sanat"),
  _k('kedb-049', _edb, 'Tanzimat', "Tanzimat edebiyatında ilkler", "İlk yerli roman: Taaşşuk-ı Talat ve Fitnat.\nİlk edebî roman: İntibah.\nİlk realist roman: Araba Sevdası.\nİlk köy romanı: Karabibik.\nİlk tiyatro: Şair Evlenmesi.\nİlk özel gazete: Tercüman-ı Ahval.\nİlk makale: Tercüman-ı Ahval Mukaddimesi.\nİlk çeviri roman: Telemak.", "Karabibik: ilk köy romanı"),
  _k('kedb-050', _edb, 'Servet-i Fünun', "Servet-i Fünun edebiyatının özellikleri", "“Sanat, sanat içindir.”\nAğır ve süslü dil; aruz ölçüsü.\nŞiirde parnasizm ve sembolizm, romanda realizm ve natüralizm.\nKonu bütünlüğü, anjambman, “kulak için kafiye”.\nSone, terza-rima, serbest müstezat.\nSanatçılar: Tevfik Fikret, Cenap Şahabettin, Halit Ziya, Mehmet Rauf.", "Kulak için kafiye"),
  _k('kedb-051', _edb, 'Servet-i Fünun', "Servet-i Fünun roman ve hikâyeleri", "Halit Ziya Uşaklıgil: Mai ve Siyah, Aşk-ı Memnu, Kırık Hayatlar.\nMehmet Rauf: Eylül (ilk psikolojik roman).\nHüseyin Cahit Yalçın: Hayal İçinde.\nKonular: aydın kesimin bireysel sorunları, hayal-gerçek çatışması, İstanbul.", "Eylül: ilk psikolojik roman"),
  _k('kedb-052', _edb, 'Millî Edebiyat', "Millî Edebiyat döneminin özellikleri", "Dilde sadeleşme: İstanbul Türkçesi esas alınır.\nHece ölçüsü, halk edebiyatı nazım biçimleri.\nKonular İstanbul dışına, Anadolu'ya açılır.\nMillî konular ve Türkçülük düşüncesi.\nSanatçılar: Ömer Seyfettin, Ziya Gökalp, Mehmet Emin Yurdakul, Ali Canip Yöntem, Halide Edib, Yakup Kadri, Refik Halit.", "Sade dil, hece, Anadolu"),
  _k('kedb-053', _edb, 'Millî Edebiyat', "Bağımsız sanatçılar", "Hüseyin Rahmi Gürpınar: natüralist, mizahi, halk için sanat; Şıpsevdi, Gulyabani, Mürebbiye.\nAhmet Rasim: fıkra ve anı; Şehir Mektupları.\nMehmet Âkif Ersoy: Safahat; aruzla toplumcu şiir.\nYahya Kemal Beyatlı: neoklasik, saf şiir.", "Hüseyin Rahmi: mizah"),
  _k('kedb-054', _edb, 'Millî Edebiyat', "Yahya Kemal Beyatlı", "Divan şiirini çağdaş bir anlayışla yorumlamıştır (neoklasik).\nAruz ölçüsünü kullanmış; hece ölçüsüyle tek şiiri “Ok”tur.\nTemalar: İstanbul, Osmanlı tarihi, ölüm, sonsuzluk.\nEserleri: Kendi Gök Kubbemiz, Eski Şiirin Rüzgârıyla, Aziz İstanbul (nesir).", "Hece ile tek şiiri: Ok"),
  _k('kedb-055', _edb, 'Cumhuriyet Dönemi', "Beş Hececiler", "Faruk Nafiz Çamlıbel (Han Duvarları, Çoban Çeşmesi), Orhan Seyfi Orhon, Enis Behiç Koryürek, Halit Fahri Ozansoy, Yusuf Ziya Ortaç.\nHece ölçüsü ve sade dil kullanmış; Anadolu'yu ve memleket sevgisini işlemişlerdir.", "Han Duvarları: Faruk Nafiz"),
  _k('kedb-056', _edb, 'Cumhuriyet Dönemi', "Yakup Kadri'nin romanları ve dönemleri", "Kiralık Konak: kuşak çatışması.\nNur Baba: tekke yaşamı.\nSodom ve Gomore: işgal İstanbul'u.\nYaban: aydın-köylü çatışması, Kurtuluş Savaşı.\nAnkara: Cumhuriyet'in ilk yılları.\nHüküm Gecesi: Meşrutiyet dönemi.\nPanorama: 1923–1952 arası.", "Yaban: aydın – köylü"),
  _k('kedb-057', _edb, 'Cumhuriyet Dönemi', "Toplumcu gerçekçi romancılar", "Sabahattin Ali: Kuyucaklı Yusuf, Kürk Mantolu Madonna, İçimizdeki Şeytan.\nOrhan Kemal: Bereketli Topraklar Üzerinde, Murtaza; işçiler ve küçük insanlar.\nKemal Tahir: Devlet Ana, Yorgun Savaşçı; tarih ve toplum.\nYaşar Kemal: İnce Memed, Yer Demir Gök Bakır.", "Orhan Kemal: işçiler"),
  _k('kedb-058', _edb, 'Cumhuriyet Dönemi', "Modernist ve postmodern romancılar", "Oğuz Atay: Tutunamayanlar, Tehlikeli Oyunlar.\nYusuf Atılgan: Aylak Adam, Anayurt Oteli.\nAdalet Ağaoğlu: Ölmeye Yatmak, Bir Düğün Gecesi.\nBilge Karasu: Gece.\nOrhan Pamuk: Kara Kitap, Benim Adım Kırmızı (2006 Nobel Edebiyat Ödülü).", "Aylak Adam: Yusuf Atılgan"),
  _k('kedb-059', _edb, 'Cumhuriyet Dönemi', "Maviciler ve Hisarcılar", "Maviciler: Attila İlhan öncülüğünde; Garip şiirinin basitliğine tepki, zengin imgeli toplumcu şiir.\nHisarcılar: Hisar dergisi çevresi; millî değerlere bağlı, geleneği sürdüren şiir. Temsilciler: Munis Faik Ozansoy, Mehmet Çınarlı, İlhan Geçer.", "Mavi: Attila İlhan"),
  _k('kedb-060', _edb, 'Cumhuriyet Dönemi', "Cumhuriyet Dönemi tiyatrosu", "Haldun Taner: epik tiyatronun öncüsü; Keşanlı Ali Destanı.\nTurgut Özakman: Fehim Paşa Konağı.\nGüngör Dilmen: Midas'ın Kulakları.\nOrhan Asena: Hürrem Sultan.\nNecip Fazıl: Bir Adam Yaratmak.\nRecep Bilginer, Cevat Fehmi Başkut.", "Keşanlı Ali: epik tiyatro"),
  _k('kedb-061', _edb, 'Edebî Akımlar', "Natüralizm ve parnasizm", "Natüralizm: realizmin ileri aşaması; deney, kalıtım ve çevrenin belirleyiciliği (determinizm). Temsilci: Émile Zola; bizde Hüseyin Rahmi, Nabizade Nazım.\nParnasizm: realizmin şiire yansıması; biçim kusursuzluğu, nesnellik. Bizde Tevfik Fikret, Yahya Kemal.", "Natüralizm: kalıtım ve çevre"),
  _k('kedb-062', _edb, 'Edebî Akımlar', "20. yüzyıl akımları", "Empresyonizm: izlenimcilik.\nEkspresyonizm: dışavurumculuk.\nFütürizm: gelecekçilik; makine ve hız (Nazım Hikmet etkilenmiştir).\nDadaizm: her şeyi reddetme.\nSürrealizm: bilinçaltı, rüya (Garip ve İkinci Yeni etkilenmiştir).\nEgzistansiyalizm: varoluşçuluk.", "Sürrealizm: bilinçaltı"),
  _k('kedb-063', _edb, 'Türler', "Dünya edebiyatında ilk örnekler", "İlk roman: Don Kişot (Cervantes).\nHikâye türünün ilk örneği: Decameron (Boccaccio).\nDeneme türünün kurucusu: Montaigne (Denemeler).\nFabl: Ezop, La Fontaine; Doğu'da Beydeba (Kelile ve Dimne).\nİlk gazete yazıları ve makale Batı'da 17–18. yüzyılda gelişti.", "Don Kişot: ilk roman"),
  _k('kedb-064', _edb, 'Türler', "Trajedi, komedi ve dram", "Trajedi: konusu tarih ve mitolojiden; kahramanları soylu; üç birlik kuralı; acıklı olaylar sahnede gösterilmez.\nKomedi: gündelik yaşam, sıradan kişiler; güldürerek düşündürür.\nDram: acıklı ve gülünç olaylar bir arada; kişiler her kesimden; kurallar esnektir.", "Üç birlik: zaman, yer, olay"),
  _k('kedb-065', _edb, 'Türler', "Karagöz ve orta oyunu", "Karagöz bölümleri: mukaddime (giriş), muhavere (söyleşme), fasıl (asıl oyun), bitiş.\nKarşıtlık: Karagöz (halk) – Hacivat (okumuş).\nOrta oyunu: Pişekâr – Kavuklu; bölümleri mukaddime, muhavere (arzbar ve tekerleme), fasıl, bitiş.\nMeddah: tek kişilik gösteri.", "Pişekâr ↔ Hacivat"),
  _k('kedb-066', _edb, 'Türler', "Masal ve fabl", "Masal: olağanüstü olaylar; yer ve zaman belirsiz; tekerlemeyle başlar; iyiler ödüllendirilir. Bölümleri: döşeme, serim, düğüm, çözüm, dilek.\nFabl: kahramanları hayvan ya da bitkidir; sonunda ders verilir (kıssadan hisse); kişileştirme ve intak vardır.", "Masalda döşeme bölümü var"),
  _k('kedb-067', _edb, 'Türler', "Anlatıcı ve bakış açıları", "İlahi (hâkim) bakış açısı: anlatıcı her şeyi bilir; kişilerin aklından geçenleri de aktarır.\nKahraman bakış açısı: olayın kahramanı “ben” diliyle anlatır.\nGözlemci bakış açısı: anlatıcı yalnızca gördüklerini bir kamera gibi aktarır.", "İlahi: her şeyi bilir"),

  // ─── TARİH ─────────────────────────────────────────────
  _k('ktar-031', _tar, 'Tarih Bilimi', "Tarih araştırmasının yöntemi", "Kaynak arama (tarama) → tasnif (sınıflandırma) → tahlil (çözümleme) → tenkit (eleştiri) → terkip (sentez).\nTarih deney ve gözlem yapamaz; belgeye dayanır, yer ve zaman göstererek neden-sonuç ilişkisi kurar.", "Tarama, tasnif, tahlil, tenkit, terkip"),
  _k('ktar-032', _tar, 'Tarih Bilimi', "Türklerin kullandığı takvimler", "12 Hayvanlı Türk Takvimi: Güneş yılı esaslı.\nHicri Takvim: Ay yılı esaslı; başlangıcı 622 Hicret.\nCelali Takvim: Büyük Selçuklu, Melikşah dönemi; Güneş yılı.\nRumi Takvim: Osmanlı'da mali işler için; Güneş yılı.\nMiladi Takvim: 1926'dan itibaren.", "Yalnız Hicri takvim Ay yılı"),
  _k('ktar-033', _tar, 'İlk Çağ', "Tarih öncesi çağlar", "Paleolitik (Eski Taş): avcılık-toplayıcılık, ateşin bulunması, mağara resimleri.\nMezolitik (Orta Taş): geçiş dönemi.\nNeolitik (Yeni Taş): tarım, yerleşik hayat, köyler (Çatalhöyük, Çayönü).\nKalkolitik (Bakır Taş): ilk maden.\nMaden Çağları: bakır, tunç, demir.", "Neolitik: tarım ve yerleşme"),
  _k('ktar-034', _tar, 'İlk Çağ', "Mezopotamya uygarlıkları", "Sümerler: çivi yazısı, ziggurat, ilk yazılı kanunlar (Urukagina), Gılgamış Destanı.\nAkadlar: ilk imparatorluk, ilk düzenli ordu.\nBabiller: Hammurabi Kanunları (kısasa kısas).\nAsurlular: Anadolu'ya yazıyı getirdiler (Kültepe), ilk kütüphane (Ninova).", "Sümer: yazı"),
  _k('ktar-035', _tar, 'İlk Çağ', "Anadolu uygarlıkları", "Hititler: Kadeş Antlaşması, anallar (yıllıklar), Pankuş meclisi, Tavananna.\nFrigler: tarım, Kibele, tapates (kilim).\nLidyalılar: para, Kral Yolu.\nİyonlar: bilim ve felsefe, şehir devletleri (polis).\nUrartular: taş işçiliği, su kanalları (Şamran).", "Lidya: para"),
  _k('ktar-036', _tar, 'İlk Çağ', "Mısır, Fenike ve İbrani uygarlıkları", "Mısır: hiyeroglif, papirüs, piramitler, mumyalama, Güneş takvimi, geometri.\nFenikeliler: harf yazısı (alfabe), deniz ticareti, koloniler.\nİbraniler: tek tanrılı inanç.\nPersler: satraplık (eyalet) sistemi, posta örgütü.", "Fenike: alfabe"),
  _k('ktar-037', _tar, 'İlk Türk Devletleri', "Göktürkler (Kök Türkler)", "552'de Bumin Kağan kurdu.\n“Türk” adını kullanan ilk devlet.\nİpek Yolu için Sasani ve Bizans ile ilişki kurdular.\nII. Göktürk (Kutluk) Devleti: Bilge Kağan, Kültigin, Vezir Tonyukuk.\nOrhun Yazıtları ve 38 harfli Göktürk alfabesi.", "Türk adını ilk kullanan"),
  _k('ktar-038', _tar, 'İlk Türk Devletleri', "Uygurlar", "744'te Kutluk Bilge Kül Kağan kurdu.\nBögü Kağan döneminde Maniheizm benimsendi; savaşçılık zayıfladı.\nYerleşik hayata geçen ilk Türk devleti.\nKâğıt, matbaa, 18 harfli Uygur alfabesi.\nTarım, şehirler, tapınak ve saray mimarisi.", "İlk yerleşik Türk devleti"),
  _k('ktar-039', _tar, 'İlk Türk Devletleri', "İlk Türk devletlerinde devlet ve toplum", "Kut: yönetme yetkisinin Tanrı'dan geldiği inancı.\nTöre: yazısız hukuk kuralları.\nKurultay (toy): danışma meclisi.\nİkili teşkilat: doğu-batı yönetimi.\nGök Tanrı inancı; kurgan (mezar), balbal (mezar taşı), yuğ (cenaze töreni).", "Kut, töre, kurultay"),
  _k('ktar-040', _tar, 'İslam Tarihi', "Hz. Muhammed dönemi önemli olaylar", "622 Hicret.\n624 Bedir: ilk zafer.\n625 Uhud.\n627 Hendek: savunma savaşı.\n628 Hudeybiye Antlaşması: Mekkeliler Müslümanları hukuken tanıdı.\n630 Mekke'nin fethi.\n632 Veda Haccı ve Veda Hutbesi.", "Bedir, Uhud, Hendek"),
  _k('ktar-041', _tar, 'İslam Tarihi', "Emeviler ve Abbasiler", "Emeviler: halifelik saltanata dönüştü; Arap milliyetçiliği (mevali politikası); İslam Kuzey Afrika ve İspanya'ya yayıldı; ilk İslam parası.\nAbbasiler: ümmetçilik politikası; Türklere görev verildi (Samarra); Beytü'l-Hikme ile bilim ve çeviri hareketi.", "Emevi: mevali, Abbasi: ümmet"),
  _k('ktar-042', _tar, 'Türk-İslam Devletleri', "Talas Savaşı (751)", "Abbasiler ile Çin arasında yapıldı; Karluklar Abbasileri destekledi.\nSonuçları: Orta Asya'nın Çin egemenliğine girmesi önlendi; Türkler arasında İslamiyet yayılmaya başladı; kâğıt yapımı Çin dışına çıktı.", "Türk – İslam yakınlaşması"),
  _k('ktar-043', _tar, 'Türk-İslam Devletleri', "Büyük Selçuklu Devleti'nde yönetim", "1040 Dandanakan: kuruluş.\n1048 Pasinler: Bizans'la ilk savaş.\n1071 Malazgirt: Anadolu'nun kapıları açıldı.\nİkta sistemi: toprak geliri karşılığı asker besleme.\nAtabey: melikleri yetiştiren devlet adamı.\nNizamülmülk: Siyasetname, Nizamiye Medreseleri.", "İkta → Osmanlı'da tımar"),
  _k('ktar-044', _tar, 'Türk-İslam Devletleri', "Türk-İslam bilginleri", "Farabi: felsefe, müzik; “Muallim-i Sani”.\nİbn Sina: tıp; “El-Kanun fi't-Tıb”.\nBiruni: astronomi, coğrafya, matematik.\nHarezmi: cebirin kurucusu.\nUluğ Bey: astronomi, rasathane.\nAli Kuşçu: astronomi, matematik.", "Harezmi: cebir"),
  _k('ktar-045', _tar, 'Türkiye Tarihi', "Haçlı Seferleri'nin sonuçları", "Dinî: Kiliseye ve din adamlarına güven azaldı.\nSiyasi: derebeyler zayıfladı, krallar güçlendi.\nEkonomik: Akdeniz limanları (Venedik, Ceneviz) gelişti.\nTeknik: barut, pusula, kâğıt, matbaa Avrupa'ya taşındı.\nTürklerin batıya ilerleyişi bir süre durdu.", "Feodalite zayıfladı"),
  _k('ktar-046', _tar, 'Türkiye Tarihi', "Anadolu Selçuklu Devleti", "1176 Miryokefalon: Anadolu'nun Türk yurdu olduğu kesinleşti.\nI. Alâeddin Keykubad: en parlak dönem; Alanya tersanesi.\n1243 Kösedağ: Moğol egemenliği.\nKervansaraylar, ticarette sigorta sistemi.\nAhilik: esnaf örgütü.", "Miryokefalon: tapu senedi"),
  _k('ktar-047', _tar, 'Osmanlı Kuruluş', "Kuruluş dönemi hükümdarlarının ilkleri", "Osman Bey: ilk vergi (bac), Koyunhisar Savaşı.\nOrhan Bey: Bursa'nın fethi, ilk düzenli ordu, ilk medrese, Rumeli'ye geçiş, divan.\nI. Murad: Edirne'nin fethi, Yeniçeri Ocağı, pençik sistemi, Rumeli Beylerbeyliği, “ülke padişah ve oğullarının malıdır”.", "I. Murad: yeniçeri"),
  _k('ktar-048', _tar, 'Osmanlı Kuruluş', "Fetret Devri ve toparlanma", "1402 Ankara Savaşı: Yıldırım Bayezid Timur'a yenildi.\nFetret Devri (1402–1413): şehzadeler arası taht kavgası.\nÇelebi Mehmed: devleti yeniden toparladı (ikinci kurucu).\nII. Murad: Varna (1444) ve II. Kosova (1448) zaferleri; Balkanlar kesin Türk yurdu oldu.", "Çelebi Mehmed: ikinci kurucu"),
  _k('ktar-049', _tar, 'Osmanlı Yükselme', "Fatih Sultan Mehmed dönemi", "1453 İstanbul'un fethi.\nKanunname-i Âl-i Osman: merkezî otoriteyi güçlendirdi.\nKırım'ın alınması (1475): Karadeniz Türk gölü oldu.\n1473 Otlukbeli: Akkoyunlular yenildi.\nİlk altın para, Sahn-ı Seman Medreseleri, Topkapı Sarayı.", "Kanunname ve Kırım"),
  _k('ktar-050', _tar, 'Osmanlı Kültür ve Medeniyet', "Divan-ı Hümayun üyeleri", "Vezir-i azam: padişahın vekili.\nKazasker: adalet ve eğitim işleri.\nDefterdar: maliye.\nNişancı: tuğra çeker, toprak kayıtlarını tutar.\nKaptan-ı derya: donanma.\nŞeyhülislam: kararların dine uygunluğu (fetva).\nReisülküttap: sonradan dış işleri.", "Nişancı: tuğra"),
  _k('ktar-051', _tar, 'Osmanlı Kültür ve Medeniyet', "Osmanlı toprak sistemi", "Miri arazi (devlete ait): dirlik (has, zeamet, tımar), vakıf, mukataa, ocaklık, yurtluk, paşmaklık.\nDirlik: geliri hizmet karşılığı görevlilere bırakılan toprak.\nHas: en yüksek gelirli; zeamet: orta; tımar: en düşük gelirli.\nTımar sahibi cebelü (atlı asker) besler.", "Has > zeamet > tımar"),
  _k('ktar-052', _tar, 'Osmanlı Kültür ve Medeniyet', "Osmanlı ordusu", "Kapıkulu askerleri: devşirme kökenli, maaşlı (ulufe); Yeniçeriler (piyade), Kapıkulu sipahileri (süvari).\nEyalet askerleri: Tımarlı sipahiler (en kalabalık grup), akıncılar, azaplar.\nDonanma: Kaptan-ı derya yönetiminde.", "Tımarlı sipahi maaş almaz"),
  _k('ktar-053', _tar, 'Osmanlı Kültür ve Medeniyet', "Osmanlı'da yönetici sınıflar ve eğitim", "Seyfiye: askerî ve yönetim (vezir, beylerbeyi).\nİlmiye: eğitim, hukuk, din (kadı, müderris, şeyhülislam).\nKalemiye: bürokrasi (nişancı, defterdar).\nEnderun: devşirmelerin yetiştirildiği saray okulu.\nMedrese: temel eğitim kurumu.", "Seyfiye, ilmiye, kalemiye"),
  _k('ktar-054', _tar, 'Osmanlı 17. Yüzyıl', "17. yüzyıl ıslahatçıları", "Kuyucu Murad Paşa: Celali isyanlarını bastırdı.\nII. (Genç) Osman: Yeniçeri Ocağı'nı kaldırmak isteyen ilk padişah.\nIV. Murad: otoriteyi zorla sağladı; Koçi Bey Risalesi.\nTarhuncu Ahmed Paşa: ilk modern bütçe.\nKöprülüler: şartlı sadrazamlık.", "Genç Osman: ilk girişim"),
  _k('ktar-055', _tar, 'Osmanlı 18. Yüzyıl', "Lale Devri yenilikleri (1718–1730)", "İlk Türk matbaası (İbrahim Müteferrika).\nAvrupa'ya ilk geçici elçiler (Yirmisekiz Çelebi Mehmed, Paris).\nÇiçek aşısı, itfaiye (tulumbacı) ocağı.\nKâğıt, kumaş ve çini imalathaneleri.\nPatrona Halil İsyanı ile sona erdi.", "İlk matbaa"),
  _k('ktar-056', _tar, 'Osmanlı 18. Yüzyıl', "III. Selim ve Nizam-ı Cedit", "Nizam-ı Cedit ordusu ve İrad-ı Cedit hazinesi.\nAvrupa başkentlerinde ilk daimî elçilikler.\nMühendishane-i Berri-i Hümayun (kara mühendis okulu).\nKabakçı Mustafa İsyanı ile tahttan indirildi.", "Daimî elçilikler"),
  _k('ktar-057', _tar, 'Osmanlı 19. Yüzyıl', "Milliyetçilik isyanları", "Fransız İhtilali'nin yaydığı milliyetçilik çok uluslu imparatorlukları sarstı.\nSırp İsyanı (1804): ilk isyan; ayrıcalık elde ettiler.\nYunan (Rum) İsyanı (1821): 1829 Edirne Antlaşması'yla bağımsız olan ilk ulus.\nNavarin (1827): Osmanlı donanması yakıldı.", "İlk bağımsız: Yunanistan"),
  _k('ktar-058', _tar, 'Osmanlı 19. Yüzyıl', "Osmanlı'yı kurtarmaya yönelik fikir akımları", "Osmanlıcılık: din ve ırk ayrımı gözetmeden tüm tebaayı eşit saymak (Tanzimat, Meşrutiyet).\nİslamcılık: Müslümanları halife çevresinde birleştirmek (II. Abdülhamid).\nTürkçülük: Türklerin birliği (İttihat ve Terakki).\nBatıcılık: Batı'nın bilim ve tekniğini almak.", "Balkan Savaşları Osmanlıcılığı bitirdi"),
  _k('ktar-059', _tar, 'Osmanlı 19. Yüzyıl', "93 Harbi ve Berlin Antlaşması", "1877–1878 Osmanlı-Rus Savaşı (93 Harbi).\nAyastefanos Antlaşması uygulanmadı.\n1878 Berlin Antlaşması: Sırbistan, Karadağ ve Romanya bağımsız oldu; Kars, Ardahan, Batum Rusya'ya verildi; Kıbrıs'ın yönetimi İngiltere'ye bırakıldı; Ermeni meselesi uluslararası sorun oldu.", "Kars, Ardahan, Batum"),
  _k('ktar-060', _tar, 'Osmanlı 20. Yüzyıl', "II. Meşrutiyet ve 31 Mart Olayı", "1908: II. Meşrutiyet ilan edildi; Kanun-i Esasi yeniden yürürlüğe girdi.\n31 Mart Olayı (1909): rejime karşı ilk ayaklanma; Hareket Ordusu bastırdı (kurmay başkanı Mustafa Kemal).\nII. Abdülhamid tahttan indirildi; 1909 değişiklikleriyle padişahın yetkileri kısıtlandı.", "Hareket Ordusu"),
  _k('ktar-061', _tar, 'I. Dünya Savaşı', "Savaşın nedenleri ve bloklar", "Nedenler: ham madde ve pazar arayışı (sömürgecilik), silahlanma, Alman-İngiliz ekonomik rekabeti, Alsas-Loren sorunu, Rusya'nın Panslavizm politikası.\nİtilaf: İngiltere, Fransa, Rusya (sonra İtalya, ABD).\nİttifak: Almanya, Avusturya-Macaristan, Osmanlı, Bulgaristan.", "Kıvılcım: Saraybosna suikastı"),
  _k('ktar-062', _tar, 'I. Dünya Savaşı', "Osmanlı'nın savaştığı cepheler", "Taarruz: Kafkas (Sarıkamış), Kanal.\nSavunma: Çanakkale, Irak (Kut'ül-Amare zaferi), Suriye-Filistin, Hicaz-Yemen.\nYardım: Galiçya, Makedonya, Romanya.\nMustafa Kemal: Çanakkale, Kafkas (Muş ve Bitlis'i geri aldı), Suriye-Filistin.", "Taarruz: Kafkas ve Kanal"),
  _k('ktar-063', _tar, 'Kurtuluş Savaşı', "Mondros Ateşkes Antlaşması (30 Ekim 1918)", "Ordu terhis edilecek, donanma teslim edilecek.\nBoğazlar İtilaf Devletleri'ne açılacak.\n7. madde: güvenliklerini tehdit eden durumda istedikleri yeri işgal edebilecekler.\n24. madde: Doğu'daki altı ilde karışıklık çıkarsa işgal edilebilecek.\nOsmanlı fiilen sona erdi.", "7 ve 24. maddeler"),
  _k('ktar-064', _tar, 'Kurtuluş Savaşı', "Cemiyetler", "Millî cemiyetler: Trakya-Paşaeli, İzmir Müdafaa-i Hukuk, Redd-i İlhak, Kilikyalılar, Doğu Anadolu Müdafaa-i Hukuk, Trabzon Muhafaza-i Hukuk, Millî Kongre.\nZararlı cemiyetler: Mavri Mira, Etnik-i Eterya, Pontus Rum, Taşnak-Hınçak (azınlık); Kürt Teali, Teali-i İslam, İngiliz Muhipleri, Wilson Prensipleri (yerli).", "Bölgesel kurtuluş → Sivas'ta birleşti"),
  _k('ktar-065', _tar, 'Kurtuluş Savaşı', "Kuvayımilliye", "İzmir'in işgali (15 Mayıs 1919) üzerine kurulan bölgesel direniş birlikleridir.\nDüzenli ordu kuruluncaya kadar düşmanı oyaladı, isyanları bastırdı.\nBelirli bir merkezden yönetilmemesi ve disiplinsizlik nedeniyle yerini düzenli orduya bıraktı.", "Düzenli orduya zaman kazandırdı"),
  _k('ktar-066', _tar, 'Kurtuluş Savaşı', "I. TBMM ve 1921 Anayasası", "23 Nisan 1920'de açıldı.\nGüçler birliği ve meclis hükûmeti sistemi.\n“Egemenlik kayıtsız şartsız milletindir.”\nTeşkilat-ı Esasiye (1921): ilk anayasa; olağanüstü koşullarda hazırlandı.\nKurucu ve savaşı yöneten meclis.", "Güçler birliği"),
  _k('ktar-067', _tar, 'Kurtuluş Savaşı', "Batı Cephesi savaşları", "I. İnönü: Londra Konferansı, Moskova Antlaşması, 1921 Anayasası, İstiklal Marşı.\nII. İnönü: İtalya çekilmeye başladı.\nKütahya-Eskişehir: geri çekilme; Tekâlif-i Milliye, Başkomutanlık Yasası.\nSakarya: Kars ve Ankara Antlaşmaları; son savunma savaşı.\nBüyük Taarruz: Mudanya Ateşkesi.", "Sakarya: son savunma"),
  _k('ktar-068', _tar, 'Kurtuluş Savaşı', "Doğu ve Güney cepheleri", "Doğu Cephesi: Ermenilere karşı Kâzım Karabekir; Gümrü Antlaşması (1920): TBMM'nin ilk askerî ve siyasi başarısı.\nGüney Cephesi: Fransızlara ve Ermenilere karşı Kuvayımilliye (Antep, Urfa, Maraş); Ankara Antlaşması (1921) ile kapandı.", "Güneyde düzenli ordu yoktu"),
  _k('ktar-069', _tar, 'İnkılaplar', "Ekonomi alanındaki gelişmeler", "1923 İzmir İktisat Kongresi: Misak-ı İktisadi.\n1924 İş Bankası.\n1925 Aşar vergisinin kaldırılması.\n1926 Kabotaj Kanunu.\n1927 Teşvik-i Sanayi Kanunu.\n1933 I. Beş Yıllık Sanayi Planı, Sümerbank.\n1935 Etibank, MTA.", "Kabotaj: 1 Temmuz 1926"),
  _k('ktar-070', _tar, 'İnkılaplar', "Eğitim ve kültür alanındaki inkılaplar", "1924 Tevhid-i Tedrisat Kanunu.\n1928 Harf İnkılabı; Millet Mektepleri.\n1931 Türk Tarih Kurumu.\n1932 Türk Dil Kurumu; Halkevleri.\n1933 Üniversite Reformu (Darülfünun → İstanbul Üniversitesi).", "1931 tarih, 1932 dil"),
  _k('ktar-071', _tar, 'Atatürk Dönemi Dış Politika', "1923–1939 dış politika gelişmeleri", "1926 Ankara Antlaşması: Musul sorunu çözüldü.\n1930 Türk-Yunan dostluğu (nüfus mübadelesi sorunu çözüldü).\n1932 Milletler Cemiyeti'ne üyelik.\n1934 Balkan Antantı.\n1936 Montrö Boğazlar Sözleşmesi.\n1937 Sadabat Paktı.\n1939 Hatay'ın katılması.", "“Yurtta barış, dünyada barış”"),
  _k('ktar-072', _tar, 'II. Dünya Savaşı', "II. Dünya Savaşı'nın sonuçları", "Mihver: Almanya, İtalya, Japonya; Müttefik: İngiltere, Fransa, SSCB, ABD.\nKonferanslar: Tahran, Yalta, Potsdam.\nHiroşima ve Nagazaki'ye atom bombası atıldı.\nBirleşmiş Milletler kuruldu (1945).\nABD ve SSCB iki süper güç oldu; sömürge imparatorlukları dağıldı.", "BM: 1945"),
  _k('ktar-073', _tar, 'Soğuk Savaş', "Soğuk Savaş dönemi", "Batı Bloku (ABD): Truman Doktrini, Marshall Planı, NATO (1949).\nDoğu Bloku (SSCB): Cominform, COMECON, Varşova Paktı (1955).\nKrizler: Berlin, Kore Savaşı, Küba Füze Krizi.\nBağlantısızlar Hareketi: Bandung Konferansı (1955).", "NATO 1949, Varşova 1955"),
  _k('ktar-074', _tar, 'Soğuk Savaş', "1945 sonrası Türkiye", "1945 BM'ye üyelik; 1946 çok partili hayata geçiş (Demokrat Parti).\n1950 DP iktidarı; Kore Savaşı'na asker gönderildi.\n1952 NATO'ya üyelik.\n1955 Bağdat Paktı.\n27 Mayıs 1960 askerî müdahale; 1961 Anayasası.\n1974 Kıbrıs Barış Harekâtı.", "NATO: 1952"),
  _k('ktar-075', _tar, 'Soğuk Savaş', "Yumuşama ve SSCB'nin dağılması", "Yumuşama (Detant): 1960'lardan sonra bloklar arası gerginliğin azalması; SALT anlaşmaları, Helsinki Nihai Senedi (1975).\nGorbaçov: glasnost (açıklık) ve perestroyka (yeniden yapılanma).\n1989 Berlin Duvarı yıkıldı; 1991 SSCB dağıldı, Türk cumhuriyetleri bağımsız oldu.", "1991: SSCB dağıldı"),

  // ─── COĞRAFYA ──────────────────────────────────────────
  _k('kcog-031', _cog, 'Dünya\'nın Şekli ve Hareketleri', "Dünya'nın şeklinin sonuçları", "Geoit: kutuplardan basık, Ekvator'dan şişkin.\nGüneş ışınlarının geliş açısı Ekvator'dan kutuplara küçülür; sıcaklık azalır.\nParalellerin boyları kutuplara doğru kısalır; meridyenler birbirine yaklaşır.\nÇizgisel hız kutuplara doğru azalır; yer çekimi kutuplarda fazladır.", "Kutuplara doğru her şey kısalır"),
  _k('kcog-032', _cog, 'Dünya\'nın Şekli ve Hareketleri', "Günlük hareketin sonuçları", "Dünya ekseni çevresinde batıdan doğuya 24 saatte döner.\nGece ve gündüz birbirini izler.\nGünlük sıcaklık farkları oluşur.\nYerel saat farkları doğar (doğuda saat ileridir).\nSürekli rüzgârlar ve okyanus akıntıları sapar (Coriolis etkisi).\nMeltem rüzgârları oluşur.", "Gece – gündüz"),
  _k('kcog-033', _cog, 'Dünya\'nın Şekli ve Hareketleri', "Yıllık hareket ve önemli tarihler", "21 Haziran: ışınlar Yengeç Dönencesi'ne dik; KYK'de en uzun gündüz.\n21 Aralık: ışınlar Oğlak Dönencesi'ne dik; KYK'de en uzun gece.\n21 Mart ve 23 Eylül: ışınlar Ekvator'a dik; gece-gündüz eşitliği (ekinoks).\nEksen eğikliği 23°27′: mevsimlerin nedeni.", "Ekinoks: 21 Mart, 23 Eylül"),
  _k('kcog-034', _cog, 'Coğrafi Konum', "Paralel ve meridyen özellikleri", "Paralel: 90 kuzey + 90 güney = 180 tane; en büyüğü Ekvator; aralarındaki uzaklık her yerde 111 km.\nMeridyen: 180 doğu + 180 batı = 360 tane; boyları eşit; aralarındaki uzaklık Ekvator'da 111 km, kutuplara doğru azalır.\nTürkiye: 36°–42° kuzey, 26°–45° doğu.", "Türkiye: 76 dakika yerel saat farkı"),
  _k('kcog-035', _cog, 'Harita Bilgisi', "Projeksiyon türleri", "Silindirik: Ekvator çevresi doğru, kutuplara doğru bozulma artar.\nKonik: orta enlemler için uygundur.\nDüzlem (ufki): kutup çevresi için uygundur.\nHaritalarda bozulmanın nedeni Dünya'nın küresel şeklidir.", "Kutuplar için düzlem"),
  _k('kcog-036', _cog, 'Harita Bilgisi', "İzohipslerin özellikleri", "Aynı yükseltideki noktaları birleştirir; iç içe kapalı eğrilerdir.\nSıklaştığı yerde eğim fazla, seyrekleştiği yerde azdır.\n0 metre eğrisi deniz kıyısını gösterir.\nİçe doğru ok: çukur (çanak).\nAkarsular izohipslerin “V” yaptığı yerlerden geçer; V'nin sivri ucu yüksekliğin arttığı yönü gösterir.", "Sık = dik yamaç"),
  _k('kcog-037', _cog, 'İklim', "Atmosferin katmanları", "Troposfer: hava olayları burada; gazların %75'i, su buharının tamamına yakını; yükseldikçe sıcaklık azalır.\nStratosfer: ozon tabakası; yatay hava hareketleri.\nMezosfer: gök taşları parçalanır.\nTermosfer (iyonosfer): radyo dalgalarını yansıtır.\nEkzosfer: uzaya geçiş.", "Hava olayları troposferde"),
  _k('kcog-038', _cog, 'İklim', "Sıcaklığın dağılışını etkileyen etmenler", "Enlem (ışınların geliş açısı), yükselti (her 200 m'de yaklaşık 1 °C azalır), karasallık-denizellik, bakı, nem, okyanus akıntıları, rüzgârlar, bitki örtüsü.\nNem günlük sıcaklık farkını azaltır.", "200 m'de 1 °C"),
  _k('kcog-039', _cog, 'İklim', "Sıcak kuşak iklimleri", "Ekvatoral: yıl boyu sıcak ve yağışlı; yağmur ormanları; konveksiyonel yağışlar.\nSavan (tropikal): yaz yağışlı, kış kurak; uzun boylu otlar.\nMuson: yazın çok yağışlı, kışın kurak; Güneydoğu Asya.\nÇöl: yağış çok az; günlük sıcaklık farkı çok fazla.", "Savan: yazı yağışlı"),
  _k('kcog-040', _cog, 'İklim', "Ilıman ve soğuk kuşak iklimleri", "Akdeniz: yaz sıcak-kurak, kış ılık-yağışlı; maki.\nIlıman okyanusal: her mevsim yağışlı; orman; Batı Avrupa.\nKarasal: sıcaklık farkı fazla; bozkır; sert karasalda tayga.\nTundra: yazın kısa süre çözülen donmuş toprak.\nKutup: sürekli buzla kaplı.", "Okyanusal: her mevsim yağış"),
  _k('kcog-041', _cog, 'Türkiye İklimi', "Türkiye'yi etkileyen basınç merkezleri", "Kışın: Sibirya yüksek basıncı (soğuk ve kuru), İzlanda alçak basıncı (ılık ve yağışlı).\nYazın: Asor yüksek basıncı (sıcak ve kuru), Basra alçak basıncı (sıcak ve kuru).\nTürkiye orta kuşakta olduğu için dört mevsim belirgindir.", "Sibirya: kışın dondurucu soğuk"),
  _k('kcog-042', _cog, 'Yer Şekilleri', "Dış kuvvetler ve karstik şekiller", "Dış kuvvetler: akarsular, rüzgârlar, buzullar, dalga ve akıntılar, yer altı suları.\nKarstik aşındırma: lapya < dolin < uvala < polye; obruk, mağara.\nKarstik biriktirme: sarkıt, dikit, sütun, traverten.\nTürkiye'de en yaygın: Akdeniz Bölgesi (Teke, Taşeli).", "Küçükten büyüğe: lapya, dolin, uvala, polye"),
  _k('kcog-043', _cog, 'Yer Şekilleri', "Jeolojik zamanlar", "I. Zaman (Paleozoik): taş kömürü yatakları.\nII. Zaman (Mezozoik): dinozorlar; Alp-Himalaya kıvrımlarının tortulları birikti.\nIII. Zaman (Tersiyer): Alp-Himalaya dağları, linyit, petrol, tuz ve bor yatakları oluştu.\nIV. Zaman (Kuaterner): buzul çağı, insanın ortaya çıkışı, Ege ve boğazların oluşumu.", "Taş kömürü: I. Zaman"),
  _k('kcog-044', _cog, 'Yer Şekilleri', "Levha hareketleri ve deprem kuşakları", "Yer kabuğu, manto üzerinde hareket eden levhalardan oluşur.\nLevha sınırlarında deprem, volkanizma ve dağ oluşumu görülür.\nKuşaklar: Pasifik Ateş Çemberi, Alp-Himalaya kuşağı, Atlas Okyanusu ortası sırtı.\nTürkiye Alp-Himalaya kuşağındadır.", "Pasifik Ateş Çemberi"),
  _k('kcog-045', _cog, 'Türkiye\'nin Yer Şekilleri', "Türkiye'nin fay hatları", "Kuzey Anadolu Fay Hattı (KAF): Saros Körfezi'nden Van Gölü'nün kuzeyine uzanır.\nDoğu Anadolu Fay Hattı (DAF): Hatay'dan Bingöl-Karlıova'ya uzanır.\nBatı Anadolu Fay Hattı: Ege'deki grabenler boyunca.\nDeprem riski en az: Konya-Karaman çevresi, Taşeli, Mardin eşiği.", "KAF ve DAF Karlıova'da birleşir"),
  _k('kcog-046', _cog, 'Türkiye\'nin Yer Şekilleri', "Türkiye'nin dağları", "Kıvrım dağları: Kuzey Anadolu Dağları, Toroslar.\nKırık dağları (horst): Ege'de Kaz, Bozdağlar, Aydın, Menteşe dağları; aralarında graben ovaları.\nVolkanik dağlar: Ağrı, Süphan, Nemrut, Tendürek, Erciyes, Hasan Dağı, Karacadağ.", "Ege: horst ve graben"),
  _k('kcog-047', _cog, 'Türkiye\'nin Yer Şekilleri', "Türkiye'nin ova ve platoları", "Delta ovaları: Çukurova, Bafra, Çarşamba, Silifke, Gediz, Büyük ve Küçük Menderes.\nTektonik ovalar: Konya, Erzurum, Muş, Malatya.\nKarstik ovalar: Elmalı, Kestel, Acıpayam.\nPlatolar: Haymana, Cihanbeyli, Obruk, Bozok, Erzurum-Kars, Taşeli, Teke.", "Karadeniz deltaları: Bafra, Çarşamba"),
  _k('kcog-048', _cog, 'Türkiye\'nin Yer Şekilleri', "Türkiye'nin akarsuları", "Açık havza: sularını denize ulaştıran akarsular (Kızılırmak, Yeşilırmak, Sakarya, Fırat, Dicle, Seyhan, Ceyhan).\nKapalı havza: sularını denize ulaştıramayanlar (Tuz Gölü, Van Gölü, Konya havzaları, Aras-Kura Hazar'a).\nEn uzun: Kızılırmak.\nRejimleri düzensiz; enerji potansiyeli yüksek.", "En uzun: Kızılırmak"),
  _k('kcog-049', _cog, 'Türkiye\'nin Yer Şekilleri', "Türkiye'nin gölleri (oluşumlarına göre)", "Tektonik: Tuz, Beyşehir, Eğirdir, Sapanca, İznik, Manyas, Ulubat.\nVolkanik: Nemrut (krater/kaldera), Meke (maar).\nKarstik: Salda, Kestel, Avlan.\nSet gölleri: Van (volkanik), Tortum (heyelan), Bafa ve Köyceğiz (alüvyal), Büyük ve Küçük Çekmece (kıyı).", "Van: volkanik set"),
  _k('kcog-050', _cog, 'Su Kaynakları', "Akarsularla ilgili kavramlar", "Debi (akım): akarsuyun belirli bir kesitinden saniyede geçen su miktarı.\nRejim: debinin yıl içindeki değişimi (düzenli – düzensiz).\nHavza: akarsuyun sularını topladığı alan.\nDenge profili: aşındırma ve biriktirmenin dengelendiği durum.\nSu bölümü çizgisi: havzaları ayıran sınır.", "Rejim: akımın yıllık seyri"),
  _k('kcog-051', _cog, 'Bitki Örtüsü', "Türkiye'de bitki toplulukları", "Orman: Karadeniz kıyıları (her mevsim yağış); geniş ve iğne yapraklı.\nMaki: Akdeniz ikliminde kısa boylu, sert yapraklı, her dem yeşil çalılar (zeytin, defne, mersin, kocayemiş).\nGarig: makinin tahrip edildiği yerde.\nBozkır (step): İç ve Güneydoğu Anadolu.\nDağ çayırları: Doğu Anadolu (Erzurum-Kars).", "Maki tahrip olursa garig"),
  _k('kcog-052', _cog, 'Nüfus', "Nüfus yoğunluğu türleri", "Aritmetik yoğunluk: toplam nüfus / yüz ölçümü.\nTarımsal yoğunluk: tarımla uğraşan nüfus / tarım alanı.\nFizyolojik yoğunluk: toplam nüfus / tarım alanı.\nNüfus artış hızı = (doğum − ölüm) + net göç.\nTürkiye'de ilk nüfus sayımı 1927'de yapıldı.", "Fizyolojik: toplam nüfus / tarım alanı"),
  _k('kcog-053', _cog, 'Nüfus', "Nüfus piramitleri", "Geniş tabanlı (üçgen): doğum oranı yüksek, yaşam süresi kısa; az gelişmiş ülkeler.\nÇan biçimi: doğum oranı azalmış; gelişmekte olan ülkeler.\nDar tabanlı (kovan, asimetrik): doğum oranı düşük, yaşlı nüfus fazla; gelişmiş ülkeler.\nPiramit; yaş, cinsiyet, doğum oranı hakkında bilgi verir.", "Geniş taban = çok doğum"),
  _k('kcog-054', _cog, 'Nüfus', "Türkiye'nin nüfus politikaları", "1923–1963: nüfus artışını teşvik (savaş kayıpları, iş gücü gereksinimi).\n1963–1980: nüfus planlaması, artış hızını düşürme.\n1980–2000'ler: aile planlaması ve nitelikli nüfus.\nSon dönem: yaşlanan nüfusa karşı genç nüfusu koruma politikaları.", "1963: planlı dönem"),
  _k('kcog-055', _cog, 'Yerleşme', "Şehirlerin fonksiyonları", "Sanayi: Kocaeli, Bursa, Karabük.\nLiman-ticaret: İstanbul, Mersin, İzmir.\nTurizm: Antalya, Muğla, Nevşehir.\nYönetim (idari): Ankara.\nMadencilik: Zonguldak, Batman.\nTarım: Rize, Adana.\nKültür-üniversite: Eskişehir.\nDinî: Kudüs, Mekke.", "Zonguldak: taş kömürü"),
  _k('kcog-056', _cog, 'Ekonomik Faaliyetler', "Ekonomik faaliyet türleri", "Birincil: tarım, hayvancılık, ormancılık, balıkçılık, madencilik.\nİkincil: sanayi, inşaat, enerji üretimi.\nÜçüncül: ticaret, ulaşım, eğitim, sağlık, turizm, bankacılık.\nDördüncül: bilgi üretimi, yazılım, AR-GE.\nBeşincil: üst düzey yöneticilik, karar vericiler.", "Gelişmişlik arttıkça hizmet artar"),
  _k('kcog-057', _cog, 'Ekonomik Faaliyetler', "Türkiye'de tarım ürünleri", "Çay: Rize. Fındık: Ordu, Giresun. Pamuk: Şanlıurfa, Çukurova, Ege. Tütün: Ege. Zeytin, incir, üzüm: Ege. Muz: Anamur, Alanya. Turunçgil: Akdeniz. Şeker pancarı ve buğday: İç Anadolu. Ayçiçeği: Trakya (Ergene). Kayısı: Malatya. Mercimek: Güneydoğu Anadolu.", "Ayçiçeği: Trakya"),
  _k('kcog-058', _cog, 'Ekonomik Faaliyetler', "Türkiye'nin madenleri", "Bor: Balıkesir, Kütahya, Eskişehir (dünya rezervinde ilk sırada).\nDemir: Divriği (Sivas), Hekimhan (Malatya).\nBakır: Murgul (Artvin), Küre (Kastamonu), Maden (Elazığ).\nKrom: Guleman (Elazığ), Fethiye.\nBoksit: Seydişehir (Konya).\nTaş kömürü: Zonguldak.", "Demir: Divriği"),
  _k('kcog-059', _cog, 'Ekonomik Faaliyetler', "Türkiye'nin enerji kaynakları", "Linyit: en yaygın; Afşin-Elbistan, Soma, Tunçbilek, Yatağan.\nPetrol: Batman, Adıyaman.\nHidroelektrik: Fırat üzerinde Keban, Karakaya, Atatürk barajları.\nJeotermal: Denizli (Sarayköy), Aydın (Germencik).\nRüzgâr: Ege ve Marmara kıyıları.\nGüneş: Güneydoğu Anadolu ve Akdeniz.", "Linyit en yaygın"),
  _k('kcog-060', _cog, 'Ekonomik Faaliyetler', "Sanayi, ulaşım ve turizm", "Sanayi kuruluşu için: ham madde, enerji, sermaye, iş gücü, ulaşım, pazar.\nTürkiye'de sanayi en çok Marmara'da toplanmıştır.\nUlaşımda yer şekilleri belirleyicidir; kara yolu en çok kullanılır.\nTurizm: deniz (Akdeniz, Ege), kültür (İstanbul, Kapadokya), kış (Uludağ, Palandöken), sağlık (kaplıcalar).", "Sanayi: Marmara"),
  _k('kcog-061', _cog, 'Doğal Afetler', "Doğal afetlerin sınıflandırılması", "Yer kökenli (jeolojik): deprem, volkan patlaması, heyelan, tsunami.\nAtmosfer kökenli (meteorolojik): sel, çığ, fırtına, hortum, kuraklık, don, dolu.\nCanlı kökenli (biyolojik): salgın hastalıklar, böcek istilası.\nDeprem en çok can ve mal kaybına yol açan afettir.", "Deprem: yer kökenli"),
  _k('kcog-062', _cog, 'Bölgesel Kalkınma', "Türkiye'de bölgesel kalkınma projeleri", "GAP: Güneydoğu Anadolu Projesi.\nDAP: Doğu Anadolu Projesi.\nDOKAP: Doğu Karadeniz Projesi.\nKOP: Konya Ovası Projesi.\nZBK: Zonguldak-Bartın-Karabük Projesi.\nYHGP: Yeşilırmak Havzası Gelişim Projesi.\nAmaç: bölgeler arası gelişmişlik farkını azaltmak.", "KOP: Konya Ovası"),
  _k('kcog-063', _cog, 'Küresel Ortam', "İlk uygarlık merkezleri ve kültür bölgeleri", "İlk uygarlıklar su kıyılarında kuruldu: Mezopotamya (Dicle-Fırat), Mısır (Nil), Hint (İndus-Ganj), Çin (Sarı Irmak).\nKültür bölgeleri: Türk, İslam, Batı (Avrupa), Çin, Hint, Slav, Latin Amerika, Afrika.", "Su boylarında uygarlık"),
  _k('kcog-064', _cog, 'Küresel Ortam', "Uluslararası örgütler", "BM: dünya barışı. NATO: askerî savunma. AB: Avrupa'da ekonomik ve siyasi birlik. OPEC: petrol ihraç eden ülkeler. G-20: en büyük ekonomiler. OECD: ekonomik iş birliği. KEİ: Karadeniz Ekonomik İş Birliği (merkezi İstanbul). İİT: İslam İşbirliği Teşkilatı.", "KEİ merkezi İstanbul"),
  _k('kcog-065', _cog, 'Çevre', "Sürdürülebilirlik ve doğal kaynak kullanımı", "Sürdürülebilir kalkınma: bugünün gereksinimlerini, gelecek kuşakların olanaklarını tüketmeden karşılamak.\nKarbon ayak izi: bir kişinin ya da kurumun yol açtığı sera gazı salımı.\nSu ayak izi: üretim ve tüketimde harcanan toplam su.\nGeri dönüşüm ve yenilenebilir enerji temel çözümlerdir.", "Gelecek kuşakları düşün"),

  // ─── FELSEFE GRUBU ─────────────────────────────────────
  _k('kfel-026', _fel, 'Bilgi Felsefesi', "Bilgi türleri", "Gündelik bilgi: deneme-yanılmaya dayanır, sistemsizdir.\nDinî bilgi: vahye ve inanca dayanır.\nTeknik bilgi: yarar sağlamaya yöneliktir.\nSanat bilgisi: öznel, yaratıcılığa dayalıdır.\nBilimsel bilgi: nesnel, sistemli, sınanabilir.\nFelsefi bilgi: akla dayalı, eleştirel, bütüncül.", "Bilimsel bilgi: nesnel ve sınanabilir"),
  _k('kfel-027', _fel, 'Bilgi Felsefesi', "Doğruluk ölçütleri", "Uygunluk: bilginin nesnesiyle örtüşmesi.\nTutarlılık: önceki doğru bilgilerle çelişmemesi.\nTümel uzlaşım: herkesin üzerinde anlaşması.\nApaçıklık: kuşku götürmeyecek kadar açık ve seçik olması.\nYarar: uygulamada işe yaraması (pragmatizm).", "Uygunluk: nesnesiyle örtüşme"),
  _k('kfel-028', _fel, 'İlk Çağ Felsefesi', "Sofistler", "Protagoras: “İnsan her şeyin ölçüsüdür.” Bilgi kişiden kişiye değişir (rölativizm).\nGorgias: “Hiçbir şey yoktur…” (nihilizm ve bilginin olanaksızlığı).\nPara karşılığı ders veren gezgin öğretmenlerdi; herkes için geçerli doğru bilgiyi reddettiler.", "İnsan her şeyin ölçüsü"),
  _k('kfel-029', _fel, 'Bilgi Felsefesi', "Septisizm (şüphecilik)", "Kurucusu Pyrrhon: doğru bilgiye ulaşılamaz; bu nedenle yargıdan kaçınılmalıdır (epokhe).\nTimon: neye göre, kime göre?\nYargıdan kaçınma ruh dinginliğine (ataraksia) götürür.\nDescartes'ın şüphesi ise amaç değil, yöntemdir.", "Epokhe: yargıyı askıya alma"),
  _k('kfel-030', _fel, 'İlk Çağ Felsefesi', "Epikurosçuluk ve Stoacılık", "Epikuros: mutluluk hazdır; ancak kalıcı ve ölçülü hazlar (acıdan ve korkudan kurtulmak) aranmalıdır.\nStoacılık (Zenon, Epiktetos, Seneca): doğaya ve akla uygun yaşamak; tutkulardan arınma (apatheia); elimizde olmayanları kabullenmek.", "Stoa: doğaya uygun yaşa"),
  _k('kfel-031', _fel, 'Orta Çağ Felsefesi', "Hristiyan felsefesi", "Patristik dönem – Augustinus: “Anlamak için inanıyorum.” İnanç aklın önündedir.\nSkolastik dönem – Thomas Aquinas: Aristoteles felsefesini Hristiyanlıkla uzlaştırdı; akıl ve inanç çelişmez.\nAnselmus: ontolojik Tanrı kanıtı.", "Anlamak için inanıyorum"),
  _k('kfel-032', _fel, 'İslam Felsefesi', "Kindi, Gazali ve İbn Rüşd", "Kindi: ilk İslam filozofu; felsefe ile dini uzlaştırma.\nGazali: “Tehafütü'l-Felasife”; filozofları eleştirdi; şüpheden sezgiye (kalp gözü).\nİbn Rüşd: “Tehafütü't-Tehafüt”; Aristoteles yorumcusu; akıl ile vahiy çelişmez.", "İbn Rüşd: Aristoteles yorumcusu"),
  _k('kfel-033', _fel, 'İslam Felsefesi', "İbn Haldun", "“Mukaddime” adlı eseriyle tarih felsefesinin ve sosyolojinin öncüsü sayılır.\nUmran ilmi: toplumların yapısını inceleyen bilim.\nAsabiyet: toplumu bir arada tutan dayanışma bağı.\nDevletler de canlılar gibi doğar, gelişir ve çöker.", "Mukaddime ve asabiyet"),
  _k('kfel-034', _fel, 'Yeni Çağ Felsefesi', "Rönesans felsefesi", "Hümanizm: insanı merkeze alan düşünce.\nMachiavelli: “Prens”; siyaseti ahlaktan ayırdı; “amaç aracı meşru kılar” anlayışı.\nThomas More: “Ütopya”.\nKopernik, Galilei, Kepler: bilimsel devrim; deney ve gözlem öne çıktı.", "Machiavelli: Prens"),
  _k('kfel-035', _fel, 'Yeni Çağ Felsefesi', "Bacon'ın idolleri", "Soy idolleri: insan doğasından gelen yanılgılar.\nMağara idolleri: kişisel eğitim ve alışkanlıklardan gelenler.\nÇarşı-pazar idolleri: dilin yanlış kullanımından doğanlar.\nTiyatro idolleri: otoritelere ve geleneksel öğretilere körü körüne bağlılık.", "Dört idol"),
  _k('kfel-036', _fel, 'Yeni Çağ Felsefesi', "Spinoza ve Leibniz", "Spinoza: tek töz vardır, o da Tanrı ya da doğadır (panteizm); her şey zorunluluk içinde gerçekleşir.\nLeibniz: evren “monad” adlı ruhsal tözlerden oluşur; “önceden kurulmuş uyum”; bu dünya olanaklı dünyaların en iyisidir.", "Spinoza: panteizm"),
  _k('kfel-037', _fel, 'Yeni Çağ Felsefesi', "Berkeley ve idealizm", "“Var olmak algılanmış olmaktır.”\nMaddi töz yoktur; nesneler zihindeki algı demetleridir (öznel idealizm).\nNesnelerin sürekliliğini Tanrı'nın algısı sağlar.", "Var olmak = algılanmak"),
  _k('kfel-038', _fel, '20. Yüzyıl', "Fenomenoloji, analitik felsefe, hermeneutik", "Fenomenoloji (Husserl): öze ulaşmak için ön yargıları “paranteze alma”.\nAnalitik felsefe (Wittgenstein, Russell): felsefenin işi dil çözümlemesidir.\nMantıkçı pozitivizm (Viyana Çevresi): doğrulanamayan önerme anlamsızdır.\nHermeneutik (Gadamer): anlama ve yorumlama.", "Paranteze alma: Husserl"),
  _k('kfel-039', _fel, 'Ahlak Felsefesi', "Evrensel ahlak yasası tartışması", "Yoktur diyenler: hedonizm (Aristippos), egoizm (Hobbes), anarşizm (Stirner), Nietzsche, Sartre.\nVardır – öznel temelli: Kant (ödev), Bentham ve Mill (fayda), Bergson (sezgi).\nVardır – nesnel temelli: Sokrates, Platon (iyi ideası), Farabi, Spinoza.", "Kant: ödev ahlakı"),
  _k('kfel-040', _fel, 'Ahlak Felsefesi', "Ahlak felsefesinin temel kavramları", "İyi – kötü: ahlakça değerli olan ve olmayan.\nErdem: iyiye yönelme yatkınlığı.\nVicdan: kişinin kendi eylemini yargılama gücü.\nÖzgürlük: seçme ve eyleme olanağı.\nSorumluluk: eylemin sonuçlarını üstlenme.\nÖzgürlük olmadan sorumluluk olmaz.\nAhlak (yerel) – etik (ahlakın felsefesi).", "Özgürlük → sorumluluk"),
  _k('kfel-041', _fel, 'Siyaset Felsefesi', "Siyaset felsefesinin temel kavramları", "İktidar: yönetme gücü.\nMeşruiyet: iktidarın hukuka ve yönetilenlerin rızasına dayanması.\nEgemenlik: en üstün buyurma gücü.\nWeber'e göre otorite türleri: geleneksel, karizmatik, yasal-ussal.\nSivil toplum: devlet dışında gönüllü örgütlenmeler.", "Meşruiyet: rıza ve hukuk"),
  _k('kfel-042', _fel, 'Sanat Felsefesi', "Estetiğin temel kavramları", "Estetik: güzelliği ve sanatı inceleyen felsefe dalı.\nEstetik özne (seyirci), estetik nesne (eser), estetik yargı.\nKant: güzel, çıkarsız hoşlanmanın nesnesidir; estetik yargı özneldir ama genel geçerlik ister.\nHegel: sanatta güzellik doğadakinden üstündür.", "Kant: çıkarsız hoşlanma"),
  _k('kfel-043', _fel, 'Din Felsefesi', "Tanrı'nın varlığıyla ilgili görüşler", "Teizm: Tanrı vardır, evreni yaratmış ve yönetmektedir.\nDeizm: Tanrı yaratmış ama müdahale etmez.\nPanteizm: Tanrı ve evren özdeştir.\nPanenteizm: evren Tanrı'nın içindedir.\nAteizm: Tanrı yoktur.\nAgnostisizm: bilinemez.", "Deizm: müdahale yok"),
  _k('kfel-044', _fel, 'Din Felsefesi', "Tanrı'nın varlığına ilişkin kanıtlar", "Ontolojik kanıt: en yetkin varlık düşüncesi var oluşu da içerir (Anselmus, Descartes).\nKozmolojik kanıt: her şeyin bir nedeni vardır; ilk neden Tanrı'dır (Aristoteles, Farabi, İbn Sina).\nTeleolojik (düzen ve amaç) kanıtı: evrendeki düzen bir düzenleyiciyi gösterir.", "Teleolojik: düzen"),
  _k('kfel-045', _fel, 'Bilim Felsefesi', "Bilime klasik ve çağdaş yaklaşım", "Ürün olarak bilim (mantıkçı pozitivizm – Reichenbach, Carnap): bilim, doğrulanabilir önermelerden oluşan birikimli bir üründür.\nEtkinlik olarak bilim (Kuhn, Toulmin): bilim, bilim insanları topluluğunun tarihsel ve toplumsal etkinliğidir.", "Ürün ↔ etkinlik"),
  _k('kfel-046', _fel, 'Mantık', "Akıl ilkeleri", "Özdeşlik: A, A'dır.\nÇelişmezlik: bir şey hem A hem A olmayan olamaz.\nÜçüncü hâlin olanaksızlığı: bir şey ya A'dır ya da A değildir.\nYeter sebep: her şeyin bir nedeni vardır (Leibniz).", "Dört ilke"),
  _k('kfel-047', _fel, 'Mantık', "Kıyas (tasım)", "İki öncülden zorunlu bir sonuç çıkarma.\nBüyük terim, küçük terim ve orta terim bulunur; orta terim sonuçta yer almaz.\nİki olumsuz öncülden sonuç çıkmaz; iki tikel öncülden sonuç çıkmaz.\nSonuç, öncüllerin zayıf olanına (tikel, olumsuz) bağlıdır.", "Orta terim sonuçta yok"),
  _k('kfel-048', _fel, 'Mantık', "Sembolik mantıkta eklemler", "Değilleme (~p): doğruluk değeri tersine döner.\nVe (p ∧ q): ikisi de doğruysa doğru.\nVeya (p ∨ q): en az biri doğruysa doğru.\nİse (p → q): yalnız p doğru, q yanlışken yanlış.\nAncak ve ancak (p ↔ q): değerler aynıysa doğru.\nTotoloji: her durumda doğru; çelişki: her durumda yanlış.", "Totoloji: hep doğru"),
  _k('kfel-049', _fel, 'Psikoloji', "Psikoloji ekolleri", "Yapısalcılık (Wundt): bilincin ögeleri, iç gözlem.\nİşlevselcilik (W. James): zihnin uyum işlevi.\nDavranışçılık (Watson, Skinner): gözlenebilir davranış.\nPsikanaliz (Freud): bilinçaltı; id, ego, süperego.\nGestalt: bütün, parçaların toplamından farklıdır.\nHümanist (Maslow, Rogers), bilişsel (Piaget).", "Freud: bilinçaltı"),
  _k('kfel-050', _fel, 'Psikoloji', "Öğrenme türleri", "Klasik koşullanma (Pavlov): uyarıcılar arası bağ.\nEdimsel koşullanma (Skinner): pekiştirme ve ceza.\nModel alma (Bandura): gözlem yoluyla.\nKavrama yoluyla (Köhler): içgörü, “aha” yaşantısı.\nGizil öğrenme (Tolman): farkında olmadan.\nDeneme-yanılma (Thorndike).", "Skinner: pekiştirme"),
  _k('kfel-051', _fel, 'Psikoloji', "Savunma mekanizmaları", "Bastırma: rahatsız edici yaşantıyı bilinçaltına itme.\nYansıtma: kendi kusurunu başkasına yükleme.\nMantığa bürüme: bahane bulma.\nYön değiştirme: öfkeyi başka hedefe yöneltme.\nÖdünleme: bir alandaki eksikliği başka alanda giderme.\nYüceltme: dürtüyü toplumca onaylanan biçime çevirme.", "Yansıtma: suçu başkasına atma"),
  _k('kfel-052', _fel, 'Psikoloji', "Bellek ve unutma", "Duyusal bellek: çok kısa süreli.\nKısa süreli bellek: sınırlı kapasite (7 ± 2 birim).\nUzun süreli bellek: sınırsız, kalıcı.\nİleriye ket vurma: eski bilgi yeniyi engeller.\nGeriye ket vurma: yeni bilgi eskiyi unutturur.\nAralıklı tekrar unutmayı azaltır.", "Geriye ket: yeni, eskiyi bozar"),
  _k('kfel-053', _fel, 'Sosyoloji', "Sosyolojinin öncüleri", "İbn Haldun: umran ilmi.\nAuguste Comte: sosyolojinin kurucusu; üç hâl yasası (teolojik, metafizik, pozitif).\nÉmile Durkheim: toplumsal olgu, iş bölümü, intihar araştırması.\nMax Weber: anlayıcı sosyoloji, bürokrasi, Protestan ahlakı.\nKarl Marx: sınıf çatışması.\nZiya Gökalp: Türk sosyolojisinin kurucusu.", "Comte: üç hâl yasası"),
  _k('kfel-054', _fel, 'Sosyoloji', "Statü ve rol", "Statü: bireyin toplum içindeki konumu.\nVerilmiş statü: doğuştan (yaş, cinsiyet, soy).\nKazanılmış statü: çabayla (meslek, eğitim).\nAnahtar statü: bireyin toplumdaki en etkili konumu.\nRol: statünün gerektirdiği davranışlar.\nRol çatışması: rollerin birbiriyle çelişmesi.", "Rol: statünün davranış yönü"),
  _k('kfel-055', _fel, 'Sosyoloji', "Toplumsal gruplar ve normlar", "Birincil grup: yüz yüze, samimi ilişkiler (aile, arkadaş).\nİkincil grup: resmî, çıkara dayalı ilişkiler (şirket, sendika).\nYazılı normlar: hukuk kuralları (yaptırımı resmî).\nYazısız normlar: örf, âdet, gelenek, görenek, ahlak ve din kuralları.", "Birincil: yüz yüze"),
  _k('kfel-056', _fel, 'Sosyoloji', "Kültürle ilgili kavramlar", "Kültürlenme: bireyin kendi toplumunun kültürünü öğrenmesi.\nKültürleşme: farklı kültürlerin karşılıklı etkileşimi.\nKültür şoku: yabancı kültüre uyum güçlüğü.\nKültürel gecikme: manevi kültürün maddi kültürdeki değişime ayak uyduramaması.\nKültür emperyalizmi: bir kültürün başkasına dayatılması.", "Gecikme: manevi geride kalır"),
  _k('kfel-057', _fel, 'Sosyoloji', "Toplumsal tabakalaşma ve hareketlilik", "Kapalı tabakalaşma: geçiş yoktur (kölelik, kast, feodal düzen).\nAçık tabakalaşma: geçiş olanaklıdır (sınıf sistemi).\nYatay hareketlilik: aynı tabakada yer ya da meslek değiştirme.\nDikey hareketlilik: tabakalar arasında yükselme ya da düşme.", "Dikey: tabaka değişir"),

  // ─── DİN KÜLTÜRÜ ───────────────────────────────────────
  _k('kdin-021', _din, 'İnanç', "Din ve vahiy", "Din: akıl sahibi insanları kendi iradeleriyle iyiye ve doğruya yönelten ilahi kurallar bütünü.\nVahiy: Allah'ın emir ve öğütlerini peygamberlerine bildirmesi.\nİman: kalp ile tasdik, dil ile ikrar.\nAkıl ve irade sorumluluğun ön koşuludur.", "İman: tasdik ve ikrar"),
  _k('kdin-022', _din, 'İnanç', "Allah'ın sıfatları", "Zati sıfatlar (yalnız Allah'a özgü): vücud, kıdem, beka, vahdaniyet, muhalefetün li'l-havadis, kıyam bi-nefsihi.\nSubuti sıfatlar: hayat, ilim, semi (işitme), basar (görme), irade, kudret, kelam, tekvin (yaratma).", "6 zati, 8 subuti"),
  _k('kdin-023', _din, 'İnanç', "Melekler ve görevleri", "Cebrail: vahiy.\nMikail: doğa olayları ve rızık.\nİsrafil: sûra üfleme.\nAzrail: can alma.\nKiramen Kâtibin: iyilik ve kötülükleri yazan melekler.\nMünker ve Nekir: kabirde sorgu.\nMelekler nurdan yaratılmıştır; yemez, içmez, günah işlemezler.", "Dört büyük melek"),
  _k('kdin-024', _din, 'İnanç', "Ahiretle ilgili kavramlar", "Ecel: ömrün sonu.\nBerzah: ölümle yeniden diriliş arasındaki kabir hayatı.\nKıyamet: evrendeki düzenin son bulması.\nBaas: yeniden diriliş.\nMahşer: toplanma yeri.\nMizan: amellerin tartılması.\nSırat, cennet, cehennem.", "Baas: yeniden diriliş"),
  _k('kdin-025', _din, 'İbadet', "İbadet çeşitleri ve temel ilkeleri", "Bedenî: namaz, oruç.\nMalî: zekât, sadaka, kurban.\nHem bedenî hem malî: hac.\nİlkeler: niyet (amaç Allah rızası), ihlas (samimiyet), Kur'an ve sünnete uygunluk.\nSalih amel: Allah'ın rızasına uygun her güzel davranış.", "Hac: beden ve mal"),
  _k('kdin-026', _din, 'İbadet', "Namazın farzları", "Dışındaki farzlar (şartlar): hadesten taharet (abdest), necasetten taharet (temizlik), setr-i avret (örtünme), istikbal-i kıble, vakit, niyet.\nİçindeki farzlar (rükünler): iftitah tekbiri, kıyam, kıraat, rükû, secde, son oturuş (kade-i ahire).", "6 şart + 6 rükün"),
  _k('kdin-027', _din, 'İbadet', "Abdest, gusül ve teyemmüm", "Abdestin farzları: yüzü yıkamak, kolları dirseklerle birlikte yıkamak, başı mesh etmek, ayakları topuklarla birlikte yıkamak.\nGusül: ağza ve burna su vermek, bütün vücudu yıkamak.\nTeyemmüm: su bulunmadığında ya da kullanılamadığında temiz toprakla alınan abdest.", "Abdestin 4 farzı"),
  _k('kdin-028', _din, 'Kur\'an-ı Kerim', "Kur'an'ın iç düzeni", "Ayet: Kur'an'ın her bir cümlesi.\nSure: ayetlerden oluşan bölüm; 114 sure.\nCüz: yirmişer sayfalık 30 bölüm.\nHizb: bir cüzün dörtte biri.\nMushaf: Kur'an'ın kitap hâli.\nİlk inen ayetler: Alak suresinin ilk beş ayeti (“Oku!”).", "114 sure, 30 cüz"),
  _k('kdin-029', _din, 'Kur\'an-ı Kerim', "Kur'an'ın yazılması ve çoğaltılması", "Hz. Muhammed döneminde vahiy kâtiplerince yazıldı ve ezberlendi.\nHz. Ebubekir döneminde tek bir kitapta toplandı (mushaf).\nHz. Osman döneminde çoğaltılarak önemli merkezlere gönderildi.\nHarekeleme ve noktalama daha sonra yapıldı.", "Ebubekir topladı, Osman çoğalttı"),
  _k('kdin-030', _din, 'Kur\'an-ı Kerim', "Kur'an'ı anlama ile ilgili kavramlar", "Meal: Kur'an'ın başka bir dile yaklaşık çevirisi.\nTefsir: ayetlerin ayrıntılı açıklanması ve yorumu.\nTecvid: Kur'an'ı kurallarına uygun okuma bilgisi.\nHafız: Kur'an'ın tamamını ezberleyen kişi.\nMukabele: karşılıklı Kur'an okuma.", "Tefsir: yorum"),
  _k('kdin-031', _din, 'Hz. Muhammed', "Hz. Muhammed'in hayatından kesitler", "571 Mekke'de doğum.\n610 Hira'da ilk vahiy.\n615 Habeşistan'a hicret.\n620–621 Akabe Biatları.\n622 Medine'ye hicret.\n630 Mekke'nin fethi.\n632 Veda Hutbesi ve vefat.\nLakabı: Muhammedü'l-Emin (güvenilir).", "610 ilk vahiy, 622 hicret"),
  _k('kdin-032', _din, 'İslam Düşüncesi', "Hadis ve temel kaynakları", "Hadis: Hz. Peygamber'in sözleri.\nSünnet: söz, davranış ve onaylarının tümü.\nKütüb-i Sitte (altı temel hadis kitabı): Buhari, Müslim, Ebu Davud, Tirmizi, Nesai, İbn Mace.\nSened: ravi zinciri; metin: hadisin içeriği.", "Kütüb-i Sitte: altı kitap"),
  _k('kdin-033', _din, 'İslam Düşüncesi', "İcma, kıyas ve içtihat", "İcma: bir dönemdeki müçtehitlerin dinî bir konuda görüş birliğine varması.\nKıyas: hakkında hüküm bulunmayan konunun, benzer bir konunun hükmüne göre çözülmesi.\nİçtihat: müçtehidin Kur'an ve sünnetten hüküm çıkarma çabası.", "Kıyas: benzetme yoluyla hüküm"),
  _k('kdin-034', _din, 'İslam Düşüncesi', "Siyasi ve itikadi yorumlar", "Haricilik: Sıffin Savaşı'ndaki hakem olayından sonra ortaya çıktı.\nŞia: Hz. Ali ve soyunun imametini savunur.\nMutezile: aklı ön plana çıkarır.\nEşarilik ve Maturidilik: Ehl-i sünnetin itikadi mezhepleri.\nMezhepler din değil, dinin yorumlarıdır.", "Mezhep = yorum"),
  _k('kdin-035', _din, 'İslam Düşüncesi', "Alevilik – Bektaşilikte temel kavramlar", "Cem: toplu ibadet ve tören.\nDede: cemi yöneten kişi.\nSemah: cemde yapılan dinî dönüş.\nMusahiplik: yol kardeşliği.\nOn iki hizmet: cemdeki görevler.\nDört kapı kırk makam: şeriat, tarikat, marifet, hakikat.\nGülbank: toplu dua.", "Dört kapı kırk makam"),
  _k('kdin-036', _din, 'İslam Düşüncesi', "Tasavvufla ilgili kavramlar", "Tasavvuf: nefsi arındırıp Allah'a yakınlaşmayı amaçlayan düşünce ve yaşam biçimi.\nZühd: dünyaya bağlanmama.\nTakva: Allah'a karşı sorumluluk bilinci.\nİhsan: Allah'ı görüyormuş gibi kulluk etmek.\nMürşit: yol gösteren; mürit: yola giren.\nZikir: Allah'ı anmak.", "İhsan: görüyormuş gibi"),
  _k('kdin-037', _din, 'Türk-İslam Kültürü', "Anadolu'yu aydınlatan gönül erleri", "Ahmet Yesevi: Divan-ı Hikmet; Türkistan'da tasavvuf.\nHacı Bektaş Veli: Makalat; “Eline, beline, diline sahip ol.”\nMevlânâ: Mesnevi; “Ne olursan ol yine gel.”\nYunus Emre: ilahi ve sevgi.\nAhi Evran: Ahilik.\nHacı Bayram Veli: Bayramilik.", "Makalat: Hacı Bektaş"),
  _k('kdin-038', _din, 'Dinler Tarihi', "Uzak Doğu ve Hint dinleri", "Hinduizm: Vedalar, kast sistemi, karma, tenasüh.\nBudizm: Buda (Siddharta Gautama), nirvana, sekiz dilimli yol.\nCaynizm: hiçbir canlıya zarar vermeme (ahimsa).\nSihizm: Guru Nanak; tek tanrı inancı.\nKonfüçyanizm ve Taoizm: Çin. Şintoizm: Japonya.", "Ahimsa: zarar vermeme"),
  _k('kdin-039', _din, 'Ahlak', "İslam ahlakında temel değerler", "Adalet, doğruluk, emanete riayet, merhamet, cömertlik, hoşgörü, sabır, tevazu (alçak gönüllülük).\nKaçınılması gerekenler: yalan, gıybet, iftira, haset, israf, kibir, riya.\nKul hakkı: başkasının hakkını çiğnemek; hak sahibi affetmedikçe affedilmez.", "Kul hakkı helalleşmeyle"),
  _k('kdin-040', _din, 'İbadet', "Sadaka, infak ve kurban", "Zekât: belirli ölçüde zenginlerin malının kırkta birini vermesi (farz).\nFitre (fıtır sadakası): Ramazan'da verilir (vacip).\nİnfak: Allah rızası için maldan harcama.\nSadaka-i cariye: yararı süren hayır (çeşme, okul).\nKurban: Allah'a yakınlaşma amacıyla; paylaşma ve dayanışma.", "Zekât: kırkta bir"),
  _k('kdin-041', _din, 'İnanç', "Dua, tevbe ve tevekkül", "Dua: kulun Allah'tan istekte bulunması; ibadetin özüdür.\nTevbe: günahtan pişmanlık duyup bir daha yapmamaya karar vermek.\nTevekkül: gerekli tedbiri aldıktan sonra sonucu Allah'a bırakmak.\nŞükür: nimetlere karşı minnet duymak.", "Önce tedbir, sonra tevekkül"),
  _k('kdin-042', _din, 'Güncel Meseleler', "Din ve laiklik", "Laiklik: din ve devlet işlerinin birbirinden ayrılması; devletin bütün inançlara eşit uzaklıkta durması.\nDin ve vicdan özgürlüğünü güvence altına alır.\nDinin siyasi çıkarlar için kullanılmasını önler.\nTürkiye'de 1937'de anayasaya girmiştir.", "1937: anayasada laiklik"),

  // ─── İNGİLİZCE ─────────────────────────────────────────
  _k('king-031', _ing, 'Kelime', "accomplish", "başarmak, yerine getirmek\nShe accomplished all her goals before the deadline.", "achieve"),
  _k('king-032', _ing, 'Kelime', "alter", "değiştirmek\nThe new evidence altered the course of the investigation.", "change"),
  _k('king-033', _ing, 'Kelime', "anticipate", "öngörmek, beklemek\nWe anticipate a rise in prices next year.", "expect"),
  _k('king-034', _ing, 'Kelime', "contribute (to)", "katkıda bulunmak\nRegular reading contributes to vocabulary growth.", "katkı"),
  _k('king-035', _ing, 'Kelime', "convince / persuade", "ikna etmek\nHe convinced me that he was right.\nShe persuaded him to see a doctor.", "ikna"),
  _k('king-036', _ing, 'Kelime', "deny", "inkâr etmek, reddetmek\nThe minister denied the allegations.", "inkâr"),
  _k('king-037', _ing, 'Kelime', "distinguish", "ayırt etmek\nIt is hard to distinguish the twins from each other.", "ayırt etmek"),
  _k('king-038', _ing, 'Kelime', "encourage", "teşvik etmek, cesaretlendirmek\nTeachers should encourage students to ask questions.", "teşvik"),
  _k('king-039', _ing, 'Kelime', "estimate", "tahmin etmek; tahmin\nScientists estimate that the fossil is two million years old.", "yaklaşık hesap"),
  _k('king-040', _ing, 'Kelime', "expand", "genişlemek, genişletmek\nThe company plans to expand into Asian markets.", "genişlemek"),
  _k('king-041', _ing, 'Kelime', "inevitable", "kaçınılmaz\nChange is an inevitable part of life.", "unavoidable"),
  _k('king-042', _ing, 'Kelime', "obtain", "elde etmek\nYou need to obtain permission before entering the area.", "get"),
  _k('king-043', _ing, 'Kelime', "occur", "meydana gelmek; akla gelmek\nEarthquakes occur frequently in this region.", "happen"),
  _k('king-044', _ing, 'Kelime', "prevent (from)", "önlemek, engellemek\nVaccines prevent many diseases from spreading.", "engellemek"),
  _k('king-045', _ing, 'Kelime', "rely on / depend on", "güvenmek, bağlı olmak\nMany countries rely on imported energy.", "güvenmek"),
  _k('king-046', _ing, 'Kelime', "require", "gerektirmek\nThis job requires good communication skills.", "need"),
  _k('king-047', _ing, 'Kelime', "scarce", "kıt, az bulunan\nWater is scarce in desert regions.", "rare"),
  _k('king-048', _ing, 'Kelime', "severe", "şiddetli, ciddi\nThe storm caused severe damage to the coast.", "şiddetli"),
  _k('king-049', _ing, 'Kelime', "sufficient", "yeterli\nThere is not sufficient evidence to prove the theory.", "enough"),
  _k('king-050', _ing, 'Kelime', "threat / threaten", "tehdit / tehdit etmek\nPollution is a serious threat to marine life.", "tehdit"),
  _k('king-051', _ing, 'Kelime', "obvious", "açık, belli\nIt was obvious that he had not studied for the exam.", "clear"),
  _k('king-052', _ing, 'Kelime', "complex / complicated", "karmaşık\nThe human brain is an extremely complex organ.", "karmaşık"),
  _k('king-053', _ing, 'Kelime', "impact / influence", "etki; etkilemek\nSocial media has a huge impact on young people.", "effect"),
  _k('king-054', _ing, 'Kelime', "maintain", "sürdürmek, korumak; bakımını yapmak\nIt is important to maintain a healthy diet.", "sürdürmek"),
  _k('king-055', _ing, 'Deyimsel Fiiller', "give up", "bırakmak, vazgeçmek\nHe gave up smoking two years ago.\nNever give up on your dreams.", "vazgeçmek"),
  _k('king-056', _ing, 'Deyimsel Fiiller', "put off", "ertelemek\nThe meeting was put off until next week.", "postpone"),
  _k('king-057', _ing, 'Deyimsel Fiiller', "carry out", "yürütmek, gerçekleştirmek\nThe researchers carried out a survey on sleeping habits.", "conduct"),
  _k('king-058', _ing, 'Deyimsel Fiiller', "turn down", "reddetmek; (sesi) kısmak\nShe turned down the job offer.", "reject"),
  _k('king-059', _ing, 'Deyimsel Fiiller', "come across", "tesadüfen karşılaşmak, rastlamak\nI came across an old photo while cleaning the attic.", "rastlamak"),
  _k('king-060', _ing, 'Deyimsel Fiiller', "run out of", "bitmek, tükenmek\nWe have run out of milk; could you buy some?", "tükenmek"),
  _k('king-061', _ing, 'Deyimsel Fiiller', "bring about", "neden olmak, yol açmak\nThe invention of the internet brought about great changes.", "cause"),
  _k('king-062', _ing, 'Deyimsel Fiiller', "figure out / find out", "figure out: çözmek, anlamak\nfind out: öğrenmek, ortaya çıkarmak\nI cannot figure out how this machine works.", "anlamak"),
  _k('king-063', _ing, 'Deyimsel Fiiller', "look after / look for / look forward to", "look after: bakmak, ilgilenmek\nlook for: aramak\nlook forward to + V-ing: dört gözle beklemek\nI am looking forward to seeing you.", "to'dan sonra -ing"),
  _k('king-064', _ing, 'Dil Bilgisi', "Past Perfect Tense", "had + V3\nGeçmişteki iki olaydan daha önce olanı anlatır.\nWhen I arrived, the train had already left.\nBy the time, before, after, already ile sık kullanılır.", "Geçmişin geçmişi"),
  _k('king-065', _ing, 'Dil Bilgisi', "Reported Speech (dolaylı anlatım)", "Aktarırken zaman bir derece geçmişe kayar:\nam/is → was, do → did, did/have done → had done, will → would, can → could\n“I am tired.” → She said (that) she was tired.\nSoru aktarımında düz cümle sırası kullanılır: He asked where I lived.", "Bir zaman geri"),
  _k('king-066', _ing, 'Dil Bilgisi', "Causatives (ettirgen yapı)", "have + someone + V1: I had the mechanic repair my car.\nget + someone + to V1: I got him to repair my car.\nhave / get + something + V3: I had my car repaired.\nmake + someone + V1 (zorlama): She made me wait.", "have sb do / have sth done"),
  _k('king-067', _ing, 'Dil Bilgisi', "Wish clauses", "Şimdiki durum için: wish + past simple → I wish I had more time.\nGeçmiş için pişmanlık: wish + past perfect → I wish I had studied harder.\nŞikâyet / gelecek için istek: wish + would → I wish it would stop raining.", "Bir zaman geri git"),
  _k('king-068', _ing, 'Dil Bilgisi', "Gerund ve infinitive alan fiiller", "Gerund (V-ing): enjoy, avoid, mind, suggest, finish, keep, consider, deny.\nInfinitive (to V1): want, decide, hope, plan, refuse, manage, afford, promise.\nAnlamı değişenler: stop, remember, forget, try.\nI stopped smoking (bıraktım) / I stopped to smoke (içmek için durdum).", "enjoy + -ing, want + to"),
  _k('king-069', _ing, 'Dil Bilgisi', "Comparatives ve superlatives", "Kısa sıfat: -er than / the -est (taller, the tallest).\nUzun sıfat: more … than / the most … (more expensive).\nDüzensiz: good – better – best, bad – worse – worst, far – farther/further.\nas + sıfat + as: eşitlik.\nthe + comparative, the + comparative: The more you read, the more you learn.", "as … as: eşitlik"),
  _k('king-070', _ing, 'Dil Bilgisi', "Quantifiers (miktar belirteçleri)", "Sayılabilen: many, a few (birkaç), few (çok az, yetersiz).\nSayılamayan: much, a little (biraz), little (çok az, yetersiz).\nHer ikisi: some, any, a lot of, plenty of, no.\n“a few / a little” olumlu, “few / little” olumsuz anlam verir.", "few: az ve yetersiz"),
  _k('king-071', _ing, 'Bağlaçlar', "so … that / such … that", "so + sıfat/zarf + that: It was so cold that we stayed at home.\nsuch + (a/an) + sıfat + isim + that: It was such a cold day that we stayed at home.\nSonuç bildirir: “o kadar … ki”.", "such'tan sonra isim"),
  _k('king-072', _ing, 'Bağlaçlar', "in order to / so that", "Amaç bildirir.\nin order to / so as to + V1: She studies hard in order to pass the exam.\nso that + özne + can/could/will/would: She studies hard so that she can pass the exam.", "amaç"),
  _k('king-073', _ing, 'Bağlaçlar', "either … or / neither … nor / both … and", "either … or: ya … ya da\nneither … nor: ne … ne de (fiil olumlu kullanılır)\nboth … and: hem … hem de (fiil çoğul)\nnot only … but also: yalnızca … değil, aynı zamanda\nNeither Ali nor Ayşe was at home.", "neither ile olumlu fiil"),
  _k('king-074', _ing, 'Bağlaçlar', "because / because of / since / as", "because, since, as + cümle: Because it rained, we stayed in.\nbecause of, due to, owing to + isim / V-ing: Because of the rain, we stayed in.\nthanks to: sayesinde (olumlu neden).", "of varsa isim gelir"),
  _k('king-075', _ing, 'Dil Bilgisi', "Prepositions of time: in / on / at", "at: saatler ve belirli anlar (at 5 o'clock, at night, at the weekend).\non: günler ve tarihler (on Monday, on 29 October).\nin: aylar, yıllar, mevsimler, uzun süreler (in May, in 2026, in summer, in the morning).", "at saat, on gün, in ay/yıl"),
  _k('king-076', _ing, 'Okuma Stratejisi', "Paragraf tamamlama ve anlam bütünlüğü soruları", "Boşluktan önceki ve sonraki cümleyi dikkatle oku.\nZamirlere (this, they, such) ve bağlaçlara (however, therefore, also) bak: bunlar bir önceki cümleye gönderme yapar.\nAkışı bozan cümlede konu ya da zaman değişimini ara.\nZaman uyumuna dikkat et.", "Zamir ve bağlaç ipucudur"),
];
